// 3D 体验馆的全局状态（zustand）。
// 只放跨系统共享的标量状态；每帧变化的玩家位姿不进 store，走模块级可变对象（world.ts）。

import { create } from "zustand";

export type CameraMode = "reveal" | "follow" | "focus" | "overview";

type ExperienceState = {
  started: boolean;
  /** 0 → 1 揭幕进度（start 点击后由 reveal 系统驱动到 1） */
  revealProgress: number;
  selectedId: string;
  nearId: string;
  hoveredId: string;
  /** 已点亮过的节点集合（HUD 进度） */
  visited: string[];
  soundEnabled: boolean;
  cameraMode: CameraMode;
  /** 震屏烈度 0..1（trauma），每帧平方衰减后用于相机抖动 */
  trauma: number;

  start: () => void;
  setRevealProgress: (value: number) => void;
  select: (id: string) => void;
  closePanel: () => void;
  setNear: (id: string) => void;
  setHovered: (id: string) => void;
  markVisited: (id: string) => void;
  setSoundEnabled: (enabled: boolean) => void;
  setCameraMode: (mode: CameraMode) => void;
  addTrauma: (amount: number) => void;
  setTrauma: (value: number) => void;
  reset: () => void;
};

const initialState = {
  started: false,
  revealProgress: 0,
  selectedId: "",
  nearId: "",
  hoveredId: "",
  visited: [] as string[],
  soundEnabled: true,
  cameraMode: "reveal" as CameraMode,
  trauma: 0,
};

export const useExperienceStore = create<ExperienceState>((set) => ({
  ...initialState,
  start: () => set({ started: true }),
  setRevealProgress: (value) => set({ revealProgress: value }),
  select: (id) =>
    set((state) => ({
      selectedId: id,
      cameraMode: "follow",
      visited: state.visited.includes(id) ? state.visited : [...state.visited, id],
    })),
  closePanel: () => set({ selectedId: "" }),
  setNear: (id) => set({ nearId: id }),
  setHovered: (id) => set({ hoveredId: id }),
  markVisited: (id) =>
    set((state) => (state.visited.includes(id) ? state : { visited: [...state.visited, id] })),
  setSoundEnabled: (enabled) => set({ soundEnabled: enabled }),
  setCameraMode: (mode) => set({ cameraMode: mode }),
  addTrauma: (amount) => set((state) => ({ trauma: Math.min(1, state.trauma + amount) })),
  setTrauma: (value) => set({ trauma: Math.max(0, Math.min(1, value)) }),
  reset: () => set({ ...initialState }),
}));
