/**
 * themeUtils.ts — 模块主题配色工具层
 *
 * 问题：暗色模式下各模块外壳使用近黑硬编码色（#0a1520 / #1a2030 等），
 * 与深色背景 #070a12 几乎同色，节点"融入"背景不可见。
 *
 * 方案：darkShell() 将暗色外壳基色向节点色相偏移并整体提亮，
 * 每个模块的机身带上可辨识的色彩倾向，同时保持暗色科技质感。
 */

import * as THREE from 'three';

/**
 * 暗色外壳提亮：base 基色向节点 color 色相混合 tint 比例，再整体提亮 lift。
 * - tint 控制"染色"程度（0.2~0.4 足够辨认色相又不喧宾夺主）
 * - lift 控制最低亮度，确保与 #070a12 背景拉开对比
 */
export function darkShell(base: string, color: string, tint = 0.3, lift = 0.16): string {
  const c = new THREE.Color(base).lerp(new THREE.Color(color), tint);
  c.r = Math.min(1, c.r + lift);
  c.g = Math.min(1, c.g + lift);
  c.b = Math.min(1, c.b + lift);
  return '#' + c.getHexString();
}
