import { useMemo } from 'react';
import * as THREE from 'three';
import { RoundedBox } from '@react-three/drei';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * KnowledgeBaseModule - 知识库存储腔体模块
 * 业务能力：knowledge知识库，海量文档向量存储
 */
export function KnowledgeBaseModule({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Derive light-mode colors from the node's palette color
  const shellBase = new THREE.Color(color);
  const shellColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const topColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.6).getHexString();
  const baseColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.4).getHexString();
  const ventColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const portColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.25).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const shellColor = dark ? darkShell('#1a1510', color) : shellColorLight;
  const topColor = dark ? darkShell('#221a10', color) : topColorLight;
  const baseColor = dark ? darkShell('#141008', color, 0.25, 0.12) : baseColorLight;
  const ventColor = dark ? darkShell('#120e08', color, 0.22, 0.1) : ventColorLight;
  const portColor = dark ? darkShell('#0e0a05', color, 0.22, 0.1) : portColorLight;

  const storageLayers = useMemo(() => {
    const layers = [];
    const layerCount = 8;
    for (let i = 0; i < layerCount; i++) {
      const yPos = -0.35 + (i * 0.1);
      layers.push({
        position: [0, yPos, 0] as [number, number, number],
        key: `layer-${i}`,
      });
    }
    return layers;
  }, []);

  const indicatorLights = useMemo(() => {
    const lights = [];
    const rows = 4;
    const cols = 5;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const xPos = -0.3 + (c * 0.15);
        const yPos = -0.2 + (r * 0.13);
        lights.push({
          position: [xPos, yPos, 0.46] as [number, number, number],
          key: `light-${r}-${c}`,
        });
      }
    }
    return lights;
  }, []);

  return (
    <group>
        {/* === 厚重大圆角方盒腔体外壳 === */}
        <RoundedBox
          args={[1.0, 0.9, 0.9]}
          radius={0.08}
          smoothness={4}
          position={[0, 0, 0]}
        >
          <meshStandardMaterial
            color={shellColor}
            roughness={0.7}
            metalness={0.8}
            emissive={color}
            emissiveIntensity={0.15 * emissiveScale}
          />
        </RoundedBox>

        {/* === 外壳顶部加厚盖板 === */}
        <RoundedBox
          args={[1.02, 0.08, 0.92]}
          radius={0.03}
          smoothness={4}
          position={[0, 0.46, 0]}
        >
          <meshStandardMaterial
            color={topColor}
            roughness={0.6}
            metalness={0.85}
            emissive={color}
            emissiveIntensity={0.1 * emissiveScale}
          />
        </RoundedBox>

        {/* === 外壳底部基座 === */}
        <RoundedBox
          args={[1.04, 0.06, 0.94]}
          radius={0.02}
          smoothness={4}
          position={[0, -0.47, 0]}
        >
          <meshStandardMaterial
            color={baseColor}
            roughness={0.8}
            metalness={0.75}
          />
        </RoundedBox>

        {/* === 前面板半透明磨砂玻璃观察窗 === */}
        <RoundedBox
          args={[0.85, 0.7, 0.02]}
          radius={0.04}
          smoothness={4}
          position={[0, 0, 0.455]}
        >
          <meshStandardMaterial
            color={color}
            roughness={0.3}
            metalness={0.2}
            transparent
            opacity={0.35}
            emissive={color}
            emissiveIntensity={0.08 * emissiveScale}
          />
        </RoundedBox>

        {/* === 内部多层晶体存储介质 === */}
        {storageLayers.map((layer) => (
          <RoundedBox
            key={layer.key}
            args={[0.7, 0.025, 0.6]}
            radius={0.005}
            smoothness={2}
            position={layer.position}
          >
            <meshStandardMaterial
              color={color}
              roughness={0.25}
              metalness={0.6}
              transparent
              opacity={0.7}
              emissive={color}
              emissiveIntensity={0.4 * emissiveScale}
            />
          </RoundedBox>
        ))}

        {/* === 表面索引指示灯点阵 === */}
        {indicatorLights.map((light) => (
          <mesh key={light.key} position={light.position}>
            <sphereGeometry args={[0.018, 16, 16]} />
            <meshStandardMaterial
              color={color}
              emissive={color}
              emissiveIntensity={1.2 * emissiveScale}
              roughness={0.2}
              metalness={0.3}
            />
          </mesh>
        ))}

        {/* === 左侧散热格栅装饰条 === */}
        {[0, 1, 2, 3].map((i) => (
          <RoundedBox
            key={`left-vent-${i}`}
            args={[0.02, 0.08, 0.5]}
            radius={0.005}
            smoothness={2}
            position={[-0.52, -0.15 + i * 0.1, 0]}
          >
            <meshStandardMaterial
              color={ventColor}
              roughness={0.9}
              metalness={0.7}
            />
          </RoundedBox>
        ))}

        {/* === 右侧散热格栅装饰条 === */}
        {[0, 1, 2, 3].map((i) => (
          <RoundedBox
            key={`right-vent-${i}`}
            args={[0.02, 0.08, 0.5]}
            radius={0.005}
            smoothness={2}
            position={[0.52, -0.15 + i * 0.1, 0]}
          >
            <meshStandardMaterial
              color={ventColor}
              roughness={0.9}
              metalness={0.7}
            />
          </RoundedBox>
        ))}

        {/* === 顶部状态指示条 === */}
        <RoundedBox
          args={[0.5, 0.015, 0.04]}
          radius={0.005}
          smoothness={2}
          position={[0, 0.5, 0.3]}
        >
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={0.9 * emissiveScale}
            roughness={0.2}
            metalness={0.4}
          />
        </RoundedBox>

        {/* === 底部接口面板 === */}
        <RoundedBox
          args={[0.4, 0.04, 0.06]}
          radius={0.01}
          smoothness={2}
          position={[0, -0.42, 0.46]}
        >
          <meshStandardMaterial
            color={portColor}
            roughness={0.7}
            metalness={0.8}
          />
        </RoundedBox>

        {/* === 底部接口端口 === */}
        {[-0.1, 0, 0.1].map((xOff, i) => (
          <mesh
            key={`port-${i}`}
            position={[xOff, -0.42, 0.5]}
            rotation={[Math.PI / 2, 0, 0]}
          >
            <cylinderGeometry args={[0.015, 0.015, 0.03, 12]} />
            <meshStandardMaterial
              color={portColor}
              roughness={0.5}
              metalness={0.9}
            />
          </mesh>
        ))}
    </group>
  );
}
