import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * ToolChainModule - 滑轨式模块化工具排
 * 业务能力：tools工具链，工具可插拔、串联调用
 */
export function ToolChainModule({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Derive light-mode colors from the node's palette color
  const shellBase = new THREE.Color(color);
  const metalColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const slotColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const latchColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.35).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const metalColor = dark ? darkShell('#1a2030', color) : metalColorLight;
  const glassColor = color;
  const slotColor = dark ? darkShell('#0a1015', color, 0.22, 0.1) : slotColorLight;
  const latchColor = dark ? darkShell('#0a1520', color, 0.25, 0.12) : latchColorLight;

  return (
    <group>
        {/* ===== 底座滑轨 ===== */}
        <group position={[0, -0.4, 0]}>
          {/* 主滑轨基座 */}
          <RoundedBox args={[1.6, 0.12, 0.5]} radius={0.02} position={[0, 0, 0]}>
            <meshStandardMaterial
              color={metalColor}
              roughness={0.6}
              metalness={0.8}
            />
          </RoundedBox>

          {/* 滑轨凹槽 */}
          <RoundedBox args={[1.5, 0.04, 0.08]} radius={0.01} position={[0, 0.07, -0.15]}>
            <meshStandardMaterial
              color={slotColor}
              roughness={0.4}
              metalness={0.9}
              emissive={color}
              emissiveIntensity={0.3 * emissiveScale}
            />
          </RoundedBox>
          <RoundedBox args={[1.5, 0.04, 0.08]} radius={0.01} position={[0, 0.07, 0.15]}>
            <meshStandardMaterial
              color={slotColor}
              roughness={0.4}
              metalness={0.9}
              emissive={color}
              emissiveIntensity={0.3 * emissiveScale}
            />
          </RoundedBox>

          {/* 滑轨两端限位块 */}
          <RoundedBox args={[0.08, 0.16, 0.52]} radius={0.02} position={[-0.78, 0.02, 0]}>
            <meshStandardMaterial color={metalColor} roughness={0.5} metalness={0.8} />
          </RoundedBox>
          <RoundedBox args={[0.08, 0.16, 0.52]} radius={0.02} position={[0.78, 0.02, 0]}>
            <meshStandardMaterial color={metalColor} roughness={0.5} metalness={0.8} />
          </RoundedBox>
        </group>

        {/* ===== 工具模块1（左侧） ===== */}
        <group position={[-0.45, 0, 0]}>
            <RoundedBox args={[0.28, 0.35, 0.38]} radius={0.03} position={[0, 0, 0]}>
              <meshStandardMaterial
                color={metalColor}
                roughness={0.5}
                metalness={0.7}
              />
            </RoundedBox>

            {/* 顶部功能面板 */}
            <RoundedBox args={[0.22, 0.04, 0.3]} radius={0.01} position={[0, 0.18, 0]}>
              <meshStandardMaterial
                color={glassColor}
                roughness={0.3}
                metalness={0.2}
                transparent
                opacity={0.6}
                emissive={color}
                emissiveIntensity={0.5 * emissiveScale}
              />
            </RoundedBox>

            {/* 底部卡扣接口 */}
            <RoundedBox args={[0.24, 0.06, 0.1]} radius={0.01} position={[0, -0.18, -0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={0.8 * emissiveScale}
              />
            </RoundedBox>
            <RoundedBox args={[0.24, 0.06, 0.1]} radius={0.01} position={[0, -0.18, 0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={0.8 * emissiveScale}
              />
            </RoundedBox>

            {/* 侧面状态指示灯 */}
            <mesh position={[0.145, 0.05, 0]}>
              <cylinderGeometry args={[0.015, 0.015, 0.02, 16]} />
              <meshStandardMaterial
                color={color}
                emissive={color}
                emissiveIntensity={2 * emissiveScale}
              />
            </mesh>
        </group>

        {/* ===== 工具模块2（中间） ===== */}
        <group position={[0, 0.02, 0]}>
            <RoundedBox args={[0.3, 0.42, 0.38]} radius={0.03} position={[0, 0, 0]}>
              <meshStandardMaterial
                color={metalColor}
                roughness={0.5}
                metalness={0.7}
              />
            </RoundedBox>

            {/* 中部功能窗口 */}
            <RoundedBox args={[0.24, 0.15, 0.04]} radius={0.01} position={[0, 0.05, 0.18]}>
              <meshStandardMaterial
                color={glassColor}
                roughness={0.2}
                metalness={0.1}
                transparent
                opacity={0.5}
                emissive={color}
                emissiveIntensity={0.6 * emissiveScale}
              />
            </RoundedBox>

            {/* 顶部散热格栅 */}
            {[...Array(3)].map((_, i) => (
              <RoundedBox
                key={`vent-${i}`}
                args={[0.2, 0.015, 0.03]}
                radius={0.005}
                position={[0, 0.22, -0.1 + i * 0.1]}
              >
                <meshStandardMaterial color={slotColor} roughness={0.6} metalness={0.8} />
              </RoundedBox>
            ))}

            {/* 底部卡扣接口 */}
            <RoundedBox args={[0.26, 0.06, 0.1]} radius={0.01} position={[0, -0.22, -0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={0.8 * emissiveScale}
              />
            </RoundedBox>
            <RoundedBox args={[0.26, 0.06, 0.1]} radius={0.01} position={[0, -0.22, 0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={0.8 * emissiveScale}
              />
            </RoundedBox>

            {/* 正面状态指示条 */}
            <RoundedBox args={[0.18, 0.02, 0.01]} radius={0.005} position={[0, -0.1, 0.195]}>
              <meshStandardMaterial
                color={color}
                emissive={color}
                emissiveIntensity={1.5 * emissiveScale}
              />
            </RoundedBox>
        </group>

        {/* ===== 工具模块3（右侧，略微偏移） ===== */}
        <group position={[0.5, 0.08, 0.06]} rotation={[0, 0, 0.05]}>
            <RoundedBox args={[0.28, 0.32, 0.38]} radius={0.03} position={[0, 0, 0]}>
              <meshStandardMaterial
                color={metalColor}
                roughness={0.5}
                metalness={0.7}
              />
            </RoundedBox>

            {/* 顶部接口面板 */}
            <RoundedBox args={[0.22, 0.03, 0.28]} radius={0.01} position={[0, 0.17, 0]}>
              <meshStandardMaterial
                color={glassColor}
                roughness={0.3}
                metalness={0.2}
                transparent
                opacity={0.55}
                emissive={color}
                emissiveIntensity={0.4 * emissiveScale}
              />
            </RoundedBox>

            {/* 底部卡扣接口 */}
            <RoundedBox args={[0.24, 0.08, 0.1]} radius={0.01} position={[0, -0.17, -0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={1.2 * emissiveScale}
              />
            </RoundedBox>
            <RoundedBox args={[0.24, 0.08, 0.1]} radius={0.01} position={[0, -0.17, 0.12]}>
              <meshStandardMaterial
                color={latchColor}
                roughness={0.4}
                metalness={0.8}
                emissive={color}
                emissiveIntensity={1.2 * emissiveScale}
              />
            </RoundedBox>

            {/* 侧面解锁按钮 */}
            <mesh position={[-0.145, 0, 0]}>
              <cylinderGeometry args={[0.02, 0.02, 0.03, 16]} />
              <meshStandardMaterial
                color={color}
                roughness={0.3}
                metalness={0.6}
                emissive={color}
                emissiveIntensity={0.6 * emissiveScale}
              />
            </mesh>

            {/* 顶部状态灯 */}
            <mesh position={[0, 0.19, 0]}>
              <sphereGeometry args={[0.02, 16, 16]} />
              <meshStandardMaterial
                color={color}
                emissive={color}
                emissiveIntensity={2.5 * emissiveScale}
              />
            </mesh>
        </group>

        {/* ===== 滑轨上的空闲卡槽标记 ===== */}
        <group position={[0.25, -0.32, 0]}>
          <RoundedBox args={[0.26, 0.02, 0.36]} radius={0.005}>
            <meshStandardMaterial
              color={latchColor}
              roughness={0.5}
              metalness={0.7}
              emissive={color}
              emissiveIntensity={0.2 * emissiveScale}
              transparent
              opacity={0.4}
            />
          </RoundedBox>
        </group>
    </group>
  );
}
