// 场景组装：光照（Environment 烘焙 + 主光）、地面、节点场、玩家、氛围、后处理。
// 运行时三级降级由 ExperiencePage3D 传入 quality 档位：high / medium / low。

import { Suspense } from "react";
import { Environment, Lightformer } from "@react-three/drei";
import { EffectComposer, Bloom, Vignette, Noise } from "@react-three/postprocessing";
import { Ground } from "./Ground";
import { AgentNodeField } from "./AgentNodeField";
import { PlayerAvatar } from "./PlayerAvatar";
import { SelectionBurst } from "./SelectionBurst";
import { Atmosphere } from "./Atmosphere";
import { LinkBeam } from "./LinkBeam";
import { SpeedTrail } from "./SpeedTrail";
import { ShockwaveRing } from "./ShockwaveRing";
import { HoloLayer } from "./HoloLayer";
import { RevealSystem } from "../systems/RevealSystem";
import { CameraRig } from "../systems/CameraRig";
import { usePlayerController } from "../systems/usePlayerController";
import { palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";

export type SceneQuality = "high" | "medium" | "low";

type ExperienceSceneProps = {
  theme: ThemeName;
  motionEnabled: boolean;
  quality: SceneQuality;
};

function PlayerSystems() {
  usePlayerController();
  return null;
}

export function ExperienceScene({ theme, motionEnabled, quality }: ExperienceSceneProps) {
  const colors = palette[theme];
  const dark = theme !== "light";
  const low = quality === "low";
  const medium = quality === "medium";

  return (
    <Suspense fallback={null}>
      <Atmosphere theme={theme} sparkles={!low} />

      {/* 光照：Environment 一次性烘焙 + 关键光 */}
      <ambientLight intensity={dark ? 0.25 : 0.5} />
      <directionalLight position={[14, 20, 10]} intensity={dark ? 1.1 : 1.4} color={dark ? "#bcd8ff" : "#ffffff"} />
      <pointLight position={[0, 8, 0]} intensity={dark ? 30 : 12} color={colors.cyan} distance={26} decay={2} />
      {!low ? (
        <Environment frames={1} resolution={64}>
          <group>
            <Lightformer intensity={dark ? 3 : 2} position={[0, 8, -8]} scale={[16, 4, 1]} color={colors.cyan} />
            <Lightformer intensity={dark ? 2 : 1.5} position={[-10, 4, 6]} rotation={[0, Math.PI / 3, 0]} scale={[8, 3, 1]} color={colors.violet} />
            <Lightformer intensity={dark ? 1.6 : 1.2} position={[10, 5, 6]} rotation={[0, -Math.PI / 3, 0]} scale={[8, 3, 1]} color={colors.amber} />
          </group>
        </Environment>
      ) : null}

      <Ground theme={theme} reflector={!low} />
      <AgentNodeField theme={theme} motionEnabled={motionEnabled} />
      <PlayerAvatar theme={theme} motionEnabled={motionEnabled} />
      <SelectionBurst theme={theme} />
      <RevealSystem theme={theme} motionEnabled={motionEnabled} />

      {/* 科技感动效层：均为单 draw call / 极少 mesh 的零分配实现，high+medium 启用、low 关闭以保帧率 */}
      {!low ? (
        <>
          <LinkBeam theme={theme} motionEnabled={motionEnabled} />
          <SpeedTrail theme={theme} motionEnabled={motionEnabled} />
          <ShockwaveRing theme={theme} motionEnabled={motionEnabled} />
          <HoloLayer theme={theme} motionEnabled={motionEnabled} />
        </>
      ) : null}

      <PlayerSystems />
      <CameraRig />

      {!low && !medium ? (
        <EffectComposer multisampling={0}>
          <Bloom mipmapBlur intensity={dark ? 0.85 : 0.45} luminanceThreshold={0.62} luminanceSmoothing={0.18} />
          <Noise opacity={0.055} />
          <Vignette eskil={false} offset={0.24} darkness={dark ? 0.72 : 0.4} />
        </EffectComposer>
      ) : null}
    </Suspense>
  );
}
