import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * GUIMonitor - GUI图形可视化界面模块
 * 业务能力：桌面显示器形态，屏幕内嵌多层半透明UI面板
 */
export function GUIMonitor({ color, dark }: ModuleColorProps) {
  // 派生颜色 - 基于节点色相生成亮色模式下的色调变体
  const emissiveScale = dark ? 1.0 : 0.8;

  const shellBase = new THREE.Color(color);
  const shellColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const metalColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const slotColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const shellColor = dark ? darkShell('#2a3444', color) : shellColorLight;
  const screenBg = dark ? darkShell('#0a1520', color, 0.25, 0.12) : '#1a3a5c';
  const neckColor = dark ? darkShell('#3a4a5a', color) : metalColorLight;
  const baseColor = dark ? darkShell('#2a3a4a', color) : slotColorLight;

  return (
    <group>
        {/* === 显示器外壳主体 === */}
        <RoundedBox args={[1.4, 0.9, 0.08]} radius={0.04} position={[0, 0.35, 0]}>
          <meshStandardMaterial
            color={shellColor}
            roughness={0.6}
            metalness={0.3}
          />
        </RoundedBox>

        {/* === 屏幕显示区域（自发光） === */}
        <RoundedBox args={[1.28, 0.78, 0.02]} radius={0.02} position={[0, 0.35, 0.035]}>
          <meshStandardMaterial
            color={screenBg}
            emissive={color}
            emissiveIntensity={0.4 * emissiveScale}
            roughness={0.2}
            metalness={0.1}
          />
        </RoundedBox>

        {/* === UI面板层1 - 主内容区 === */}
        <RoundedBox args={[1.1, 0.55, 0.005]} radius={0.01} position={[0, 0.38, 0.048]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.35}
            roughness={0.8}
            metalness={0.05}
            emissive={color}
            emissiveIntensity={0.15 * emissiveScale}
          />
        </RoundedBox>

        {/* === UI面板层2 - 顶部导航条 === */}
        <RoundedBox args={[1.1, 0.12, 0.004]} radius={0.008} position={[0, 0.62, 0.05]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.4}
            roughness={0.7}
            metalness={0.05}
            emissive={color}
            emissiveIntensity={0.2 * emissiveScale}
          />
        </RoundedBox>

        {/* === UI面板层3 - 左侧工具栏 === */}
        <RoundedBox args={[0.18, 0.45, 0.004]} radius={0.008} position={[-0.48, 0.35, 0.05]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.3}
            roughness={0.75}
            metalness={0.05}
            emissive={color}
            emissiveIntensity={0.18 * emissiveScale}
          />
        </RoundedBox>

        {/* === UI面板层4 - 右侧数据卡片 === */}
        <RoundedBox args={[0.35, 0.3, 0.004]} radius={0.008} position={[0.35, 0.42, 0.052]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.32}
            roughness={0.7}
            metalness={0.05}
            emissive={color}
            emissiveIntensity={0.22 * emissiveScale}
          />
        </RoundedBox>

        {/* === UI面板层5 - 底部状态栏 === */}
        <RoundedBox args={[1.1, 0.08, 0.004]} radius={0.006} position={[0, 0.12, 0.05]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.28}
            roughness={0.75}
            metalness={0.05}
            emissive={color}
            emissiveIntensity={0.16 * emissiveScale}
          />
        </RoundedBox>

        {/* === 支架颈部 === */}
        <mesh position={[0, -0.18, 0]} rotation={[0, 0, 0]}>
          <cylinderGeometry args={[0.06, 0.08, 0.25, 16]} />
          <meshStandardMaterial
            color={neckColor}
            roughness={0.5}
            metalness={0.4}
          />
        </mesh>

        {/* === 底座圆盘 === */}
        <mesh position={[0, -0.32, 0]} rotation={[-Math.PI / 2, 0, 0]}>
          <cylinderGeometry args={[0.35, 0.38, 0.04, 24]} />
          <meshStandardMaterial
            color={baseColor}
            roughness={0.55}
            metalness={0.35}
          />
        </mesh>

        {/* === 底座装饰环 === */}
        <mesh position={[0, -0.3, 0]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.32, 0.012, 8, 32]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={0.3 * emissiveScale}
            roughness={0.4}
            metalness={0.2}
          />
        </mesh>
    </group>
  );
}
