// 3D 体验馆入口页：Canvas + HUD（复用 2D 版 class 与 i18n 键，视觉语言一致）。
// 信息架构与 2D 版共享 experience/experienceData.ts；本页只是平行渲染器。

import { ArrowLeft, ArrowUpRight, Check, ChevronRight, CircleHelp, LocateFixed, Orbit, Radio, RotateCcw, Volume2, VolumeX, X, Zap } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { Canvas } from "@react-three/fiber";
import { SettingsControls } from "../../components/SettingsControls";
import { usePreferences } from "../../hooks/usePreferences";
import { nodeById, nodes } from "../experience/experienceData";
import type { ThemeName } from "../experience/experienceData";
import { useExperienceStore } from "./store";
import { playerWorld, resetPlayerWorld } from "./world";
import { soundEngine } from "./systems/soundEngine";
import { ExperienceScene } from "./scene/ExperienceScene";
import type { SceneQuality } from "./scene/ExperienceScene";

export function ExperiencePage3D() {
  const { t } = useTranslation();
  const { resolvedTheme, motionEnabled } = usePreferences();
  const theme: ThemeName = resolvedTheme === "light" ? "light" : "dark";
  const [quality, setQuality] = useState<SceneQuality>("high");

  const started = useExperienceStore((state) => state.started);
  const selectedId = useExperienceStore((state) => state.selectedId);
  const nearId = useExperienceStore((state) => state.nearId);
  const hoveredId = useExperienceStore((state) => state.hoveredId);
  const visited = useExperienceStore((state) => state.visited);
  const soundEnabled = useExperienceStore((state) => state.soundEnabled);
  const cameraMode = useExperienceStore((state) => state.cameraMode);
  const store = useExperienceStore;
  const milestoneRef = useRef(0);

  const selectedNode = useMemo(() => (selectedId ? nodeById(selectedId) : null), [selectedId]);
  const nearNode = useMemo(() => (nearId ? nodeById(nearId) : null), [nearId]);

  // 音频开关同步到引擎
  useEffect(() => {
    soundEngine.setEnabled(soundEnabled);
  }, [soundEnabled]);

  // 探索里程碑 25/50/75% + 全探索完成音（ref 去重，每档只响一次）
  useEffect(() => {
    if (!started) {
      milestoneRef.current = 0;
      return;
    }
    const count = visited.length;
    if (count >= nodes.length) {
      if (milestoneRef.current < 100) {
        milestoneRef.current = 100;
        soundEngine.play("complete");
      }
      return;
    }
    const percent = (count / nodes.length) * 100;
    for (const tier of [75, 50, 25]) {
      if (percent >= tier && milestoneRef.current < tier) {
        milestoneRef.current = tier;
        soundEngine.play("milestone");
        break;
      }
    }
  }, [started, visited.length]);

  // 卸载时释放音频
  useEffect(() => () => soundEngine.dispose(), []);

  // E 键查看附近节点；Escape 关闭面板；V 切换 overview
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const state = store.getState();
      if (event.code === "KeyE" && state.started && state.nearId) {
        state.select(state.nearId);
        state.setCameraMode("focus");
        state.addTrauma(0.25);
        soundEngine.play("burst");
      }
      if (event.key === "Escape") {
        if (state.selectedId) state.closePanel();
        else if (state.cameraMode === "overview") state.setCameraMode("follow");
      }
      if (event.code === "KeyV" && state.started) {
        state.setCameraMode(state.cameraMode === "overview" ? "follow" : "overview");
        soundEngine.play("warp");
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [store]);

  // 相机回到 follow：玩家移动时若处于 focus 且开始走动，切回跟随
  useEffect(() => {
    let frame = 0;
    const tick = () => {
      const state = store.getState();
      if (state.cameraMode === "focus" && playerWorld.speed > 4) state.setCameraMode("follow");
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [store]);

  const handleStart = useCallback(() => {
    const state = store.getState();
    state.start();
    soundEngine.play("start");
  }, [store]);

  const handleReset = useCallback(() => {
    resetPlayerWorld(0, 11);
    store.getState().reset();
    soundEngine.play("close");
  }, [store]);

  const handleOverview = useCallback(() => {
    const state = store.getState();
    state.setCameraMode(state.cameraMode === "overview" ? "follow" : "overview");
    soundEngine.play("warp");
  }, [store]);

  const handleRefocus = useCallback(() => {
    const state = store.getState();
    state.setCameraMode("follow");
    soundEngine.play("warp");
  }, [store]);

  // 运行时性能监控：滚动 90 帧窗口 FPS，低于阈值逐级降级（useState 触发重渲染让降级真实生效）
  useEffect(() => {
    let last = performance.now();
    let raf = 0;
    let ticker = 0;
    const times: number[] = [];
    const loop = (now: number) => {
      raf = requestAnimationFrame(loop);
      const delta = now - last;
      last = now;
      times.push(delta);
      if (times.length > 90) times.shift();
      ticker += 1;
      if (ticker % 120 === 0 && times.length === 90) {
        const average = times.reduce((sum, value) => sum + value, 0) / times.length;
        const fps = 1000 / average;
        setQuality((current) => {
          if (fps < 24 && current !== "low") return "low";
          if (fps < 34 && current === "high") return "medium";
          return current;
        });
      }
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const handleCreated = useCallback(() => {
    resetPlayerWorld(0, 11);
  }, []);

  const progress = Math.round((visited.length / nodes.length) * 100);

  return (
    <main className="experience-page">
      <div className="experience-scene">
        <Canvas
          dpr={[1, 1.5]}
          frameloop="always"
          camera={{ position: [0, 46, 46], fov: 42, near: 0.1, far: 220 }}
          gl={{ antialias: true, powerPreference: "high-performance" }}
          onCreated={handleCreated}
          onPointerMissed={() => {
            const state = store.getState();
            if (state.selectedId) {
              state.closePanel();
              soundEngine.play("close");
            }
          }}
        >
          <ExperienceScene theme={theme} motionEnabled={motionEnabled} quality={quality} />
        </Canvas>

        <header className="experience-topbar">
          <Link className="experience-brand" to="/"><img src="./branding/hongyunx-mark.svg" alt="" /><span><strong>{t("brand.name")}</strong><small>INTERACTIVE FIELD / 3D</small></span></Link>
          <div className="experience-topbar__actions"><span className="experience-live"><i />{t("experience.live")}</span><SettingsControls /><Link className="experience-exit" to="/"><ArrowLeft size={14} />{t("experience.exit")}</Link></div>
        </header>

        {!started ? (
          <button className="experience-start" type="button" onClick={handleStart} aria-label={t("experience.start")}>
            <span className="experience-start__eyebrow"><Radio size={16} />{t("experience.startEyebrow")}</span>
            <strong>{t("experience.startTitle")}</strong>
            <span>{t("experience.startDescription")}</span>
            <b><Zap size={16} fill="currentColor" />{t("experience.startAction")}<ArrowUpRight size={16} /></b>
          </button>
        ) : null}

        <section className="experience-hud experience-hud--left">
          <span>{t("experience.hudMission")}</span><strong>{t("experience.hudTitle")}</strong><small>{t("experience.hudDescription")}</small>
          <div className="experience-progress"><i style={{ width: `${progress}%` }} /></div>
          <em>{t("experience.hudExplored", { count: visited.length })}</em>
        </section>

        <section className="experience-hud experience-hud--right">
          <div><span>{t("experience.hudSignal")}</span><b>{visited.length} / {nodes.length}</b></div>
          <div><span>{t("experience.hudSurfaces")}</span><b>CLI + GUI</b></div>
          <div><span>{t("experience.hudInput")}</span><b>{cameraMode === "overview" ? <Orbit size={13} /> : <LocateFixed size={13} />} {cameraMode === "overview" ? t("experience.modeOverview") : t("experience.modeWalk")}</b></div>
          <div><span>{t("experience.hudAudio")}</span><b>{soundEnabled ? "ON" : "MUTED"}</b></div>
        </section>

        <div className="experience-controls">
          <div className="experience-mode-switch" role="group" aria-label={t("experience.cameraMode")}>
            <button className={cameraMode !== "overview" ? "active" : ""} type="button" onClick={handleRefocus} aria-pressed={cameraMode !== "overview"} title={t("experience.modeWalkHint")}><LocateFixed size={14} /><span>{t("experience.modeWalk")}</span></button>
            <button className={cameraMode === "overview" ? "active" : ""} type="button" onClick={handleOverview} aria-pressed={cameraMode === "overview"} title={t("experience.modeOverviewHint")}><Orbit size={14} /><span>{t("experience.modeOverview")}</span></button>
          </div>
          <button className="experience-sound" type="button" onClick={() => store.getState().setSoundEnabled(!soundEnabled)} title={t(soundEnabled ? "experience.soundOff" : "experience.soundOn")} aria-label={t(soundEnabled ? "experience.soundOff" : "experience.soundOn")} aria-pressed={soundEnabled}>{soundEnabled ? <Volume2 size={14} /> : <VolumeX size={14} />}</button>
          <button type="button" onClick={handleReset} title={t("experience.reset")} aria-label={t("experience.reset")}><RotateCcw size={14} /></button>
          <button type="button" onClick={() => store.getState().closePanel()} title={t("experience.closePanel")} aria-label={t("experience.closePanel")}><X size={14} /></button>
        </div>

        {/* 靠近节点的上下文提示 */}
        {started && nearNode && !selectedId ? (
          <div className="experience-proximity" role="status">
            <b>{t(nearNode.labelKey).toUpperCase()}</b>
            <span>{t("experience.pressToInspect")}</span>
          </div>
        ) : null}

        {selectedNode ? (
          <aside className="experience-inspector">
            <div className="experience-inspector__header"><div><span>{t(selectedNode.labelKey).toUpperCase()}</span><h2>{t(selectedNode.titleKey)}</h2></div><button type="button" onClick={() => store.getState().closePanel()} aria-label={t("experience.closePanel")}><X size={17} /></button></div>
            <p>{t(selectedNode.bodyKey)}</p>
            <ul>{selectedNode.items.map((item) => <li key={item}><Check size={13} />{t(item)}</li>)}</ul>
            <Link to={selectedNode.id === "cli" ? "/docs/commands" : selectedNode.id === "gui" ? "/docs/gui" : "/docs"}>{t("experience.openDocs")}<ChevronRight size={15} /></Link>
          </aside>
        ) : null}

        {/* 太空舱框架：发光舱框 + 四角支架 + 舱壁刻度 + 扫描光带 + 光束（纯装饰） */}
        <div className="experience-cockpit" aria-hidden="true">
          <span className="experience-cockpit__frame" />
          <span className="experience-cockpit__corner experience-cockpit__corner--tl" />
          <span className="experience-cockpit__corner experience-cockpit__corner--tr" />
          <span className="experience-cockpit__corner experience-cockpit__corner--bl" />
          <span className="experience-cockpit__corner experience-cockpit__corner--br" />
          <span className="experience-cockpit__ticks experience-cockpit__ticks--left" />
          <span className="experience-cockpit__ticks experience-cockpit__ticks--right" />
          <span className="experience-cockpit__ticks experience-cockpit__ticks--top" />
          <span className="experience-cockpit__ticks experience-cockpit__ticks--bottom" />
          <span className="experience-cockpit__scan" />
          <span className="experience-cockpit__beam experience-cockpit__beam--a" />
          <span className="experience-cockpit__beam experience-cockpit__beam--b" />
        </div>

        <div className="experience-help"><CircleHelp size={14} />{t("experience.help3d")}</div>
        {hoveredId ? <span className="experience-hover-hint" aria-hidden="true" /> : null}
      </div>
    </main>
  );
}
