// 粒子光束：节点之间"真在传数据"的主力可视化，替代 LinkFlow 的单一青色流点。
//
// 设计要点：
// 1) 每条能力连线（16 条，与 NodeField edges 完全同源：QuadraticBezierCurve3，
//    lift(a,b)=1.1+|a-b|*0.04，中点 y=2.6）周期性从 from 端向 to 端发射一颗"脉冲彗星"：
//    一颗较亮的头部粒子 + TRAIL_COUNT 颗按指数衰减的拖尾粒子，头部沿曲线 t 0→1 前进，
//    拖尾按 t 往回偏移（t - k*TRAIL_STEP），到达后回到起点循环；相位按 edgeIndex 黄金角错开，
//    避免 16 条线的脉冲同步到达核心节点造成视觉"同步闪烁"。
// 2) 脉冲颜色 = from 端节点颜色（cyan/violet/amber 三色都有），双向链路各自携带发送方身份。
// 3) 每条线另铺 DUST_PER_LINK 颗静止"尘埃"粒子，亮度按正弦呼吸微闪（相位按 slot 打散），
//    让整条链路常亮有存在感，不至于脉冲间隙显得死黑。
// 4) revealProgress 做整体淡入；motionEnabled=false 时脉冲冻结在当前 t（尘埃微闪同时冻结相位），
//    仅 reveal 淡入仍生效，避免突兀跳变。浅色主题整体亮度压到 0.55，避免白底刺眼。
//
// 性能要点（铁律）：
// - 单 Points 单 draw call 装下全部粒子：容量 = 16×(1+TRAIL_COUNT) + 16×DUST_PER_LINK。
// - Float32Array 池 + useMemo 一次性分配；useFrame 内零 new（Vector3/Color/数组/对象字面量都不允许）。
// - curve.getPoint(t, tmpVector) 采样，tmpVector 模块级唯一实例复用。
// - 每帧只改 position/color attribute 的标量，再 needsUpdate = true。
// - 颜色亮度直接写进 color attribute 的 RGB（配合 AdditiveBlending，亮度→0 即消失），无需隐藏粒子。

import { useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, QuadraticBezierCurve3, Vector3 } from "three";
import { links, nodeById, palette, toWorld } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";

// 单条脉冲的拖尾粒子数（不含头部）
const TRAIL_COUNT = 14;
// 拖尾相邻粒子在曲线参数 t 上的回退步长（指数衰减亮度）
const TRAIL_STEP = 0.022;
// 拖尾亮度衰减系数（trail=k 时亮度 = pow(TRAIL_FALLOFF, k)）
const TRAIL_FALLOFF = 0.78;
// 头部粒子亮度放大系数（相对拖尾 k=0）
const HEAD_BOOST = 1.6;
// 脉冲从 from 到 to 走完一条线所需秒数（越小越快）
const PULSE_PERIOD = 2.2;
// 每条线的尘埃粒子数
const DUST_PER_LINK = 20;
// 尘埃基础亮度（相对脉冲头更暗，只做氛围）
const DUST_BASE = 0.22;
// 尘埃呼吸幅度与频率
const DUST_BREATH_AMP = 0.16;
const DUST_BREATH_FREQ = 1.4;
// 浅色主题整体亮度压缩（additive 在白底上容易刺眼）
const LIGHT_THEME_DIM = 0.55;
// 相邻链路相位错开的黄金角（避免同步）
const GOLDEN = 0.6180339887;

const LINK_COUNT = links.length;
const PULSE_PARTICLES_PER_LINK = 1 + TRAIL_COUNT;
const CAPACITY = LINK_COUNT * PULSE_PARTICLES_PER_LINK + LINK_COUNT * DUST_PER_LINK;

// 模块级 tmp 采样向量：getPoint 写入此处，永不 new
const tmpPoint = new Vector3();

type LinkBeamProps = {
  theme: ThemeName;
  motionEnabled: boolean;
};

export function LinkBeam({ theme, motionEnabled }: LinkBeamProps) {
  const colors = palette[theme];
  const dark = theme !== "light";

  // 曲线与恒定参数一次构建：与 NodeField edges 完全同源（同 lift、同中点 y=2.6）
  const curves = useMemo(
    () =>
      links.map(([fromId, toId]) => {
        const from = nodeById(fromId);
        const to = nodeById(toId);
        const [fx, fz] = toWorld(from.x, from.y);
        const [tx, tz] = toWorld(to.x, to.y);
        const lift = (a: number, b: number) => 1.1 + Math.abs(a - b) * 0.04;
        return new QuadraticBezierCurve3(
          new Vector3(fx, lift(from.radius, to.radius), fz),
          new Vector3((fx + tx) / 2, 2.6, (fz + tz) / 2),
          new Vector3(tx, lift(to.radius, from.radius), tz),
        );
      }),
    [],
  );

  // 每条线的 from 端节点颜色（脉冲携带发送方身份）
  const edgeColors = useMemo(
    () =>
      links.map(([fromId]) => {
        const from = nodeById(fromId);
        return new Color(colors[from.color]);
      }),
    [colors],
  );

  // 每条线尘埃的固定相位与静态位置种子（避免每帧 Math.random）
  const dustSeeds = useMemo(() => {
    const seeds = new Float32Array(LINK_COUNT * DUST_PER_LINK * 2);
    for (let edge = 0; edge < LINK_COUNT; edge += 1) {
      for (let k = 0; k < DUST_PER_LINK; k += 1) {
        const slot = edge * DUST_PER_LINK + k;
        // t 均匀分布 + 轻微抖动，相位用黄金角进一步打散
        seeds[slot * 2] = ((k + 0.5) / DUST_PER_LINK + Math.sin(edge * 12.9898 + k * 78.233) * 0.013) % 1;
        seeds[slot * 2 + 1] = (edge * GOLDEN + k * 0.377) % 1;
      }
    }
    return seeds;
  }, []);

  const positions = useMemo(() => new Float32Array(CAPACITY * 3), []);
  const particleColors = useMemo(() => new Float32Array(CAPACITY * 3), []);

  const geometry = useMemo(() => {
    const buffer = new BufferGeometry();
    buffer.setAttribute("position", new BufferAttribute(positions, 3));
    buffer.setAttribute("color", new BufferAttribute(particleColors, 3));
    return buffer;
  }, [positions, particleColors]);

  // 冻结相位：motionEnabled=false 时停在当前 clock 时间，不突变
  // 用一个 useMemo 持有可变 ref 对象（模块级规则禁止 ref 回调返回值的简写，这里直接 useRef 更清晰，
  // 但为与 SelectionBurst/LinkFlow 范式保持一致，用 useMemo 包一层可变单元）
  const frozen = useMemo(() => ({ time: 0, wasEnabled: true }), []);

  useFrame(({ clock }) => {
    const reveal = useExperienceStore.getState().revealProgress;
    if (motionEnabled) {
      frozen.time = clock.elapsedTime;
      frozen.wasEnabled = true;
    } else if (frozen.wasEnabled) {
      // 刚切到 false：冻结在当前时间，之后不再推进
      frozen.wasEnabled = false;
    }
    const time = frozen.time;
    const brightnessScale = (dark ? 1 : LIGHT_THEME_DIM) * reveal;

    const positionAttr = geometry.getAttribute("position") as BufferAttribute;
    const colorAttr = geometry.getAttribute("color") as BufferAttribute;

    // ---------- 1) 脉冲彗星（头 + 拖尾） ----------
    for (let edge = 0; edge < LINK_COUNT; edge += 1) {
      const curve = curves[edge];
      const baseColor = edgeColors[edge];
      // 脉冲头参数 t：按周期推进 + 黄金角相位错开
      const headT = (time / PULSE_PERIOD + edge * GOLDEN) % 1;

      // 头部粒子
      const headSlot = edge * PULSE_PARTICLES_PER_LINK;
      curve.getPoint(headT, tmpPoint);
      positions[headSlot * 3] = tmpPoint.x;
      positions[headSlot * 3 + 1] = tmpPoint.y;
      positions[headSlot * 3 + 2] = tmpPoint.z;
      const headBrightness = HEAD_BOOST * brightnessScale;
      particleColors[headSlot * 3] = baseColor.r * headBrightness;
      particleColors[headSlot * 3 + 1] = baseColor.g * headBrightness;
      particleColors[headSlot * 3 + 2] = baseColor.b * headBrightness;

      // 拖尾粒子：t 往回偏移 + 指数衰减
      for (let k = 0; k < TRAIL_COUNT; k += 1) {
        const slot = headSlot + 1 + k;
        let t = headT - (k + 1) * TRAIL_STEP;
        // 头刚离开 from 端时，拖尾会跨到上一周期的尾部；用包裹避免瞬移
        if (t < 0) t += 1;
        curve.getPoint(t, tmpPoint);
        positions[slot * 3] = tmpPoint.x;
        positions[slot * 3 + 1] = tmpPoint.y;
        positions[slot * 3 + 2] = tmpPoint.z;
        const trailBrightness = Math.pow(TRAIL_FALLOFF, k + 1) * brightnessScale;
        particleColors[slot * 3] = baseColor.r * trailBrightness;
        particleColors[slot * 3 + 1] = baseColor.g * trailBrightness;
        particleColors[slot * 3 + 2] = baseColor.b * trailBrightness;
      }
    }

    // ---------- 2) 沿线尘埃（静止 + 亮度呼吸） ----------
    const dustBase = LINK_COUNT * PULSE_PARTICLES_PER_LINK;
    for (let edge = 0; edge < LINK_COUNT; edge += 1) {
      const curve = curves[edge];
      const baseColor = edgeColors[edge];
      for (let k = 0; k < DUST_PER_LINK; k += 1) {
        const seedSlot = edge * DUST_PER_LINK + k;
        const slot = dustBase + seedSlot;
        const t = dustSeeds[seedSlot * 2];
        const phase = dustSeeds[seedSlot * 2 + 1];
        curve.getPoint(t, tmpPoint);
        positions[slot * 3] = tmpPoint.x;
        positions[slot * 3 + 1] = tmpPoint.y;
        positions[slot * 3 + 2] = tmpPoint.z;
        // 亮度呼吸：正弦微闪；motionEnabled=false 时 time 已冻结 → 相位静止
        const breath = DUST_BASE + DUST_BREATH_AMP * Math.sin(time * DUST_BREATH_FREQ + phase * Math.PI * 2);
        const dustBrightness = breath * brightnessScale;
        particleColors[slot * 3] = baseColor.r * dustBrightness;
        particleColors[slot * 3 + 1] = baseColor.g * dustBrightness;
        particleColors[slot * 3 + 2] = baseColor.b * dustBrightness;
      }
    }

    positionAttr.needsUpdate = true;
    colorAttr.needsUpdate = true;
  });

  return (
    <points geometry={geometry} frustumCulled={false}>
      <pointsMaterial
        size={0.22}
        vertexColors
        transparent
        blending={AdditiveBlending}
        depthWrite={false}
        sizeAttenuation
      />
    </points>
  );
}
