import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * SafetyGateModule - 双层闸机安全舱模块
 * 业务能力：安全校验、流量拦截、边界防护
 */
export function SafetyGateModule({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Color-tinted shell/metal colors for light mode
  const shellBase = new THREE.Color(color);
  const hullColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const gateColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const hullColor = dark ? darkShell('#0e1520', color) : hullColorLight;
  const gateColor = dark ? darkShell('#1a2535', color) : gateColorLight;
  const glassOpacity = dark ? 0.18 : 0.12;

  return (
      <group>
        {/* === 舱体外壳 === */}
        <RoundedBox args={[1.4, 0.5, 0.9]} radius={0.08} position={[0, 0.35, 0]}>
          <meshStandardMaterial
            color={hullColor}
            roughness={0.7}
            metalness={0.6}
            emissive={color}
            emissiveIntensity={0.15 * emissiveScale}
          />
        </RoundedBox>
        <RoundedBox args={[1.4, 0.5, 0.9]} radius={0.08} position={[0, -0.35, 0]}>
          <meshStandardMaterial
            color={hullColor}
            roughness={0.7}
            metalness={0.6}
            emissive={color}
            emissiveIntensity={0.15 * emissiveScale}
          />
        </RoundedBox>
        <RoundedBox args={[0.15, 0.2, 0.9]} radius={0.04} position={[-0.625, 0, 0]}>
          <meshStandardMaterial
            color={hullColor}
            roughness={0.7}
            metalness={0.6}
            emissive={color}
            emissiveIntensity={0.1 * emissiveScale}
          />
        </RoundedBox>
        <RoundedBox args={[0.15, 0.2, 0.9]} radius={0.04} position={[0.625, 0, 0]}>
          <meshStandardMaterial
            color={hullColor}
            roughness={0.7}
            metalness={0.6}
            emissive={color}
            emissiveIntensity={0.1 * emissiveScale}
          />
        </RoundedBox>

        {/* === 双层闸门 === */}
        <RoundedBox args={[0.9, 0.18, 0.04]} radius={0.01} position={[0, 0, 0.2]}>
          <meshStandardMaterial
            color={gateColor}
            roughness={0.5}
            metalness={0.8}
            emissive={color}
            emissiveIntensity={0.25 * emissiveScale}
          />
        </RoundedBox>
        <RoundedBox args={[0.9, 0.18, 0.04]} radius={0.01} position={[0, 0, -0.2]}>
          <meshStandardMaterial
            color={gateColor}
            roughness={0.5}
            metalness={0.8}
            emissive={color}
            emissiveIntensity={0.25 * emissiveScale}
          />
        </RoundedBox>
        <RoundedBox args={[1.0, 0.04, 0.5]} radius={0.01} position={[0, 0.12, 0]}>
          <meshStandardMaterial
            color={gateColor}
            roughness={0.6}
            metalness={0.7}
          />
        </RoundedBox>
        <RoundedBox args={[1.0, 0.04, 0.5]} radius={0.01} position={[0, -0.12, 0]}>
          <meshStandardMaterial
            color={gateColor}
            roughness={0.6}
            metalness={0.7}
          />
        </RoundedBox>

        {/* === 校验传感器阵列 === */}
        {[-0.25, 0, 0.25].map((x, i) => (
          <RoundedBox key={`sensor-top-${i}`} args={[0.06, 0.06, 0.06]} radius={0.01} position={[x, 0.22, 0]}>
            <meshStandardMaterial
              color={color}
              roughness={0.3}
              metalness={0.4}
              emissive={color}
              emissiveIntensity={0.9 * emissiveScale}
            />
          </RoundedBox>
        ))}
        {[-0.25, 0, 0.25].map((x, i) => (
          <RoundedBox key={`sensor-bottom-${i}`} args={[0.06, 0.06, 0.06]} radius={0.01} position={[x, -0.22, 0]}>
            <meshStandardMaterial
              color={color}
              roughness={0.3}
              metalness={0.4}
              emissive={color}
              emissiveIntensity={0.9 * emissiveScale}
            />
          </RoundedBox>
        ))}
        {[-0.12, 0.12].map((z, i) => (
          <RoundedBox key={`sensor-left-${i}`} args={[0.05, 0.05, 0.05]} radius={0.01} position={[-0.52, 0, z]}>
            <meshStandardMaterial
              color={color}
              roughness={0.3}
              metalness={0.4}
              emissive={color}
              emissiveIntensity={0.8 * emissiveScale}
            />
          </RoundedBox>
        ))}
        {[-0.12, 0.12].map((z, i) => (
          <RoundedBox key={`sensor-right-${i}`} args={[0.05, 0.05, 0.05]} radius={0.01} position={[0.52, 0, z]}>
            <meshStandardMaterial
              color={color}
              roughness={0.3}
              metalness={0.4}
              emissive={color}
              emissiveIntensity={0.8 * emissiveScale}
            />
          </RoundedBox>
        ))}

        {/* === 外层半透明玻璃护盾 === */}
        <RoundedBox args={[1.6, 1.0, 1.1]} radius={0.12} position={[0, 0, 0]}>
          <meshStandardMaterial
            color={color}
            roughness={0.2}
            metalness={0.1}
            transparent
            opacity={glassOpacity}
            side={THREE.DoubleSide}
            depthWrite={false}
          />
        </RoundedBox>

        {/* === 舱体边缘发光条 === */}
        <RoundedBox args={[1.3, 0.02, 0.02]} radius={0.005} position={[0, 0.6, 0.44]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.2 * emissiveScale}
            roughness={0.2}
            metalness={0.3}
          />
        </RoundedBox>
        <RoundedBox args={[1.3, 0.02, 0.02]} radius={0.005} position={[0, -0.6, 0.44]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.2 * emissiveScale}
            roughness={0.2}
            metalness={0.3}
          />
        </RoundedBox>
        <RoundedBox args={[0.8, 0.02, 0.02]} radius={0.005} position={[0, 0, 0.46]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.0 * emissiveScale}
            roughness={0.2}
            metalness={0.3}
          />
        </RoundedBox>
        <RoundedBox args={[0.8, 0.02, 0.02]} radius={0.005} position={[0, 0, -0.46]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.0 * emissiveScale}
            roughness={0.2}
            metalness={0.3}
          />
        </RoundedBox>
      </group>
  );
}
