// 揭幕系统：start 点击后 revealProgress 0→1（2.4s ease），同时从世界中心扩散一道发光涟漪。
// 节点升起由 NodeField 读 revealProgress 驱动；相机抬升由 CameraRig 驱动——单一事实源。

import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { MathUtils } from "three";
import type { Mesh, MeshBasicMaterial } from "three";
import { useExperienceStore } from "../store";
import { palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { WORLD_SIZE } from "../../experience/experienceData";

export function RevealSystem({ theme, motionEnabled }: { theme: ThemeName; motionEnabled: boolean }) {
  const ringRef = useRef<Mesh>(null);
  const colors = palette[theme];

  useFrame((_, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    const store = useExperienceStore.getState();
    if (store.started && store.revealProgress < 1) {
      const duration = motionEnabled ? 2.4 : 0.01;
      const next = MathUtils.clamp(store.revealProgress + delta / duration, 0, 1);
      // ease-out cubic
      store.setRevealProgress(1 - Math.pow(1 - next, 3));
    }
    const ring = ringRef.current;
    if (ring) {
      const progress = store.revealProgress;
      const material = ring.material as MeshBasicMaterial;
      if (!store.started || progress >= 1) {
        material.opacity = 0;
      } else {
        const scale = 1 + progress * WORLD_SIZE * 1.35;
        ring.scale.setScalar(scale);
        material.opacity = (1 - progress) * 0.85;
      }
    }
  });

  return (
    <mesh ref={ringRef} rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.06, 0]}>
      <ringGeometry args={[0.96, 1, 96]} />
      <meshBasicMaterial color={colors.cyan} transparent opacity={0} depthWrite={false} />
    </mesh>
  );
}
