// 选中爆发：固定容量粒子池（Points 单 draw call），选中节点时在其位置迸发一圈粒子。
// 环形缓冲复用，零每帧分配；配合 store.addTrauma(0.25) 的震屏，构成 Bruno 式命中反馈。

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color } from "three";
// 注意：粒子颜色写入 color attribute 后通过 additive blending 淡出（亮度→0 即消失）
import { nodes, palette, toWorld } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";

const MAX_PARTICLES = 160;
const BURST_COUNT = 40;
const LIFETIME = 0.9;

export function SelectionBurst({ theme }: { theme: ThemeName }) {
  const colors = palette[theme];
  const positions = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const velocities = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const ages = useMemo(() => new Float32Array(MAX_PARTICLES).fill(LIFETIME + 1), []);
  const particleColors = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const cursor = useRef(0);
  const lastSelected = useRef("");
  const tmpColor = useMemo(() => new Color(), []);

  const geometry = useMemo(() => {
    const buffer = new BufferGeometry();
    buffer.setAttribute("position", new BufferAttribute(positions, 3));
    buffer.setAttribute("color", new BufferAttribute(particleColors, 3));
    return buffer;
  }, [positions, particleColors]);

  // 监听 selectedId 变化 → 触发爆发
  const selectedId = useExperienceStore((state) => state.selectedId);
  useEffect(() => {
    if (!selectedId || selectedId === lastSelected.current) return;
    lastSelected.current = selectedId;
    const node = nodes.find((item) => item.id === selectedId);
    if (!node) return;
    const [x, z] = toWorld(node.x, node.y);
    tmpColor.set(colors[node.color]);
    for (let index = 0; index < BURST_COUNT; index += 1) {
      const slot = cursor.current;
      cursor.current = (cursor.current + 1) % MAX_PARTICLES;
      const angle = (Math.PI * 2 * index) / BURST_COUNT + Math.random() * 0.4;
      const speed = 3.5 + Math.random() * 3.5;
      positions[slot * 3] = x;
      positions[slot * 3 + 1] = 1.6;
      positions[slot * 3 + 2] = z;
      velocities[slot * 3] = Math.cos(angle) * speed;
      velocities[slot * 3 + 1] = 2.2 + Math.random() * 3.4;
      velocities[slot * 3 + 2] = Math.sin(angle) * speed;
      ages[slot] = 0;
      particleColors[slot * 3] = tmpColor.r;
      particleColors[slot * 3 + 1] = tmpColor.g;
      particleColors[slot * 3 + 2] = tmpColor.b;
    }
  }, [selectedId, colors, positions, velocities, ages, particleColors, tmpColor]);

  useFrame((_, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    let dirty = false;
    for (let slot = 0; slot < MAX_PARTICLES; slot += 1) {
      if (ages[slot] > LIFETIME) {
        if (positions[slot * 3 + 1] > -50) {
          positions[slot * 3 + 1] = -100; // 藏到地下
          dirty = true;
        }
        continue;
      }
      ages[slot] += delta;
      velocities[slot * 3 + 1] -= 12 * delta; // 重力
      positions[slot * 3] += velocities[slot * 3] * delta;
      positions[slot * 3 + 1] += velocities[slot * 3 + 1] * delta;
      positions[slot * 3 + 2] += velocities[slot * 3 + 2] * delta;
      const fade = Math.max(0, 1 - ages[slot] / LIFETIME);
      const base = slot * 3;
      const brightness = fade * fade;
      geometry.getAttribute("color").setXYZ(slot, particleColors[base] * brightness, particleColors[base + 1] * brightness, particleColors[base + 2] * brightness);
      dirty = true;
    }
    if (dirty) {
      geometry.getAttribute("position").needsUpdate = true;
      geometry.getAttribute("color").needsUpdate = true;
    }
  });

  return (
    <points geometry={geometry} frustumCulled={false}>
      <pointsMaterial size={0.16} vertexColors transparent blending={AdditiveBlending} depthWrite={false} sizeAttenuation />
    </points>
  );
}
