/**
 * DataFlowLine.tsx — 高级数据流连线组件
 *
 * 视觉特性：
 * 1. 渐变色彩：每条线从 fromColor 过渡到 toColor，与两端节点颜色呼应
 * 2. 立体管道：TubeGeometry 替代扁平 Line，赋予体积感
 * 3. 流光动画：沿曲线运动的发光粒子脉冲，传达数据传输感
 * 4. 外层辉光鞘：半透明外壳 + additive blending → bloom 辉光
 * 5. 形态多样：每条线的弧度/粗细由 edgeIndex 驱动，避免单调重复
 */

import { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

// ─── 类型 ──────────────────────────────────────────────────

export interface DataFlowLineProps {
  /** 曲线采样点 */
  points: [number, number, number][];
  /** 起始端颜色（hex） */
  fromColor: string;
  /** 终止端颜色（hex） */
  toColor: string;
  /** 是否暗色主题 */
  dark: boolean;
  /** 边的索引（用于错相动画） */
  edgeIndex: number;
  /** 曲线弧长（用于流速归一化） */
  arcLength?: number;
}

// ─── 常量 ──────────────────────────────────────────────────

/** 管道半径基数（暗色模式） */
const TUBE_RADIUS_DARK = 0.018;
/** 管道半径基数（浅色模式 — 加粗以增强可见性） */
const TUBE_RADIUS_LIGHT = 0.032;
/** 辉光鞘半径倍率 */
const SHEATH_RADIUS_SCALE = 2.8;
/** 流光粒子大小（暗色） */
const PULSE_SIZE_DARK = 0.06;
/** 流光粒子大小（浅色 — 加大以增强可见性） */
const PULSE_SIZE_LIGHT = 0.09;
/** 管道路径细分数 */
const TUBE_SEGMENTS = 32;
/** 管道截面细分数 */
const TUBE_RADIAL_SEGMENTS = 6;

// ─── 辅助函数 ──────────────────────────────────────────────

/**
 * 将 hex 颜色转为 THREE.Color
 */
function hexToColor(hex: string): THREE.Color {
  return new THREE.Color(hex);
}

/**
 * 从采样点重建 CatmullRom 曲线（平滑通过所有点）
 */
function buildCurveFromPoints(points: [number, number, number][]): THREE.CatmullRomCurve3 {
  const vectors = points.map(p => new THREE.Vector3(p[0], p[1], p[2]));
  return new THREE.CatmullRomCurve3(vectors, false, 'catmullrom', 0.5);
}

/**
 * 生成顶点颜色数组：沿曲线从 fromColor 线性插值到 toColor
 */
function buildGradientColors(
  _curve: THREE.CatmullRomCurve3,
  fromColor: THREE.Color,
  toColor: THREE.Color,
  segments: number,
  radialSegments: number,
): Float32Array {
  const vertexCount = (segments + 1) * (radialSegments + 1);
  const colors = new Float32Array(vertexCount * 3);
  const tempColor = new THREE.Color();

  for (let i = 0; i <= segments; i++) {
    const t = i / segments;
    tempColor.copy(fromColor).lerp(toColor, t);

    // 中间段加亮 — 形成"能量核心"视觉效果
    const midBoost = 1.0 + Math.sin(t * Math.PI) * 0.3;
    tempColor.multiplyScalar(midBoost);

    for (let j = 0; j <= radialSegments; j++) {
      const idx = (i * (radialSegments + 1) + j) * 3;
      colors[idx] = tempColor.r;
      colors[idx + 1] = tempColor.g;
      colors[idx + 2] = tempColor.b;
    }
  }

  return colors;
}

// ─── 主组件 ────────────────────────────────────────────────

export function DataFlowLine({
  points,
  fromColor,
  toColor,
  dark,
  edgeIndex,
  arcLength = 1,
}: DataFlowLineProps) {
  const pulseRef = useRef<THREE.Mesh>(null);
  const sheathRef = useRef<THREE.Mesh>(null);

  // 主题感知的管道半径和粒子大小
  const tubeRadius = dark ? TUBE_RADIUS_DARK : TUBE_RADIUS_LIGHT;
  const pulseSize = dark ? PULSE_SIZE_DARK : PULSE_SIZE_LIGHT;

  // 曲线 & 几何体（只在 points/colors/dark 变化时重建）
  const { tubeGeometry, sheathGeometry, curve } = useMemo(() => {
    const c = buildCurveFromPoints(points);
    const fc = hexToColor(fromColor);
    const tc = hexToColor(toColor);

    // 主管道几何 — 浅色模式加粗
    const tube = new THREE.TubeGeometry(c, TUBE_SEGMENTS, tubeRadius, TUBE_RADIAL_SEGMENTS, false);

    // 顶点渐变色
    const gc = buildGradientColors(c, fc, tc, TUBE_SEGMENTS, TUBE_RADIAL_SEGMENTS);
    tube.setAttribute('color', new THREE.BufferAttribute(gc, 3));

    // 外层辉光鞘（更粗、半透明）
    const sheath = new THREE.TubeGeometry(
      c,
      TUBE_SEGMENTS,
      tubeRadius * SHEATH_RADIUS_SCALE,
      TUBE_RADIAL_SEGMENTS,
      false,
    );

    return { tubeGeometry: tube, sheathGeometry: sheath, curve: c };
  }, [points, fromColor, toColor, tubeRadius]);

  // 流光脉冲动画 — 小球沿曲线运动
  useFrame((state) => {
    if (!pulseRef.current || !curve) return;

    const t = state.clock.elapsedTime;
    // 每条边不同相位 + 速度随弧长归一化（短线快、长线慢）
    const speed = 0.6 / Math.max(arcLength, 0.5);
    const phase = edgeIndex * 1.618;
    const progress = ((t * speed + phase) % 1 + 1) % 1;

    const pos = curve.getPoint(progress);
    pulseRef.current.position.copy(pos);

    // 脉冲缩放呼吸
    const breathe = 0.8 + Math.sin(t * 4 + phase) * 0.3;
    pulseRef.current.scale.setScalar(breathe);

    // 辉光鞘微弱脉动 — 浅色模式脉动幅度更大以增强可见性
    if (sheathRef.current) {
      const mat = sheathRef.current.material as THREE.MeshStandardMaterial;
      const base = dark ? 0.12 : 0.18;
      const amplitude = dark ? 0.03 : 0.06;
      mat.opacity = base + Math.sin(t * 2 + phase) * amplitude;
    }
  });

  // 混合后的发光色（用于脉冲球和 emissive）
  const blendColor = useMemo(() => {
    return '#' + hexToColor(fromColor).lerp(hexToColor(toColor), 0.5).getHexString();
  }, [fromColor, toColor]);

  // ─── 主题对比度参数 ──────────────────────────────────────
  // 浅色模式：白底上需要更强的不透明度、更高的 emissive、更粗的线条才能可见
  // 暗色模式：黑底上 emissive 自然醒目，保持精致感
  const emissiveScale = dark ? 1.0 : 1.8;
  const tubeOpacity = dark ? 0.9 : 0.95;
  const sheathBaseOpacity = dark ? 0.12 : 0.18;
  const pulseEmissiveScale = dark ? 3.5 : 5.0;

  return (
    <group>
      {/* === 1. 主管道（渐变顶点色 + emissive 自发光）=== */}
      <mesh geometry={tubeGeometry}>
        <meshStandardMaterial
          vertexColors
          emissive={blendColor}
          emissiveIntensity={1.2 * emissiveScale}
          roughness={0.3}
          metalness={0.4}
          transparent
          opacity={tubeOpacity}
          toneMapped={false}
        />
      </mesh>

      {/* === 2. 外层辉光鞘（additive blending → bloom）=== */}
      <mesh ref={sheathRef} geometry={sheathGeometry}>
        <meshStandardMaterial
          color={blendColor}
          emissive={blendColor}
          emissiveIntensity={0.6 * emissiveScale}
          transparent
          opacity={sheathBaseOpacity}
          blending={THREE.AdditiveBlending}
          depthWrite={false}
          side={THREE.BackSide}
          toneMapped={false}
        />
      </mesh>

      {/* === 3. 流光脉冲球（沿曲线运动）=== */}
      <mesh ref={pulseRef}>
        <sphereGeometry args={[pulseSize, 12, 12]} />
        <meshStandardMaterial
          color="#ffffff"
          emissive={blendColor}
          emissiveIntensity={pulseEmissiveScale}
          transparent
          opacity={0.95}
          toneMapped={false}
        />
      </mesh>
    </group>
  );
}
