import * as THREE from 'three';
import { RoundedBox } from '@react-three/drei';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * CLI 命令行交互模块 - 立式工业调试控制台
 * 业务能力：底层指令输入、物理按键操作、状态指示
 */
export function CliConsoleModule({ color, dark }: ModuleColorProps) {
  // 从 nodePalette color 派生浅色模式色调
  const shellBase = new THREE.Color(color);
  const bodyColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const slotColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const buttonColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.6).getHexString();
  const baseColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const plateColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.55).getHexString();

  // 派生颜色 — 暗色外壳注入节点色相，避免与深色背景同化
  const bodyColor = dark ? darkShell('#1a2030', color) : bodyColorLight;
  const slotColor = dark ? darkShell('#0a0e14', color, 0.22, 0.1) : slotColorLight;
  const glowEmissive = color;
  const glowIntensity = dark ? 2.5 : 1.8;
  const buttonColor = dark ? darkShell('#2a3444', color) : buttonColorLight;
  const baseColor = dark ? darkShell('#151c28', color) : baseColorLight;
  const plateColor = dark ? darkShell('#1a2535', color) : plateColorLight;

  // 主体金属材质
  const bodyMaterial = (
    <meshStandardMaterial
      color={bodyColor}
      roughness={0.7}
      metalness={0.6}
    />
  );

  // 深色凹槽材质
  const slotMaterial = (
    <meshStandardMaterial
      color={slotColor}
      roughness={0.9}
      metalness={0.3}
    />
  );

  // 自发光材质（指示灯）— 使用 nodePalette 颜色
  const glowMaterial = (
    <meshStandardMaterial
      color={glowEmissive}
      emissive={glowEmissive}
      emissiveIntensity={glowIntensity}
      roughness={0.2}
      metalness={0.1}
      toneMapped={false}
    />
  );

  // 按键材质
  const buttonMaterial = (
    <meshStandardMaterial
      color={buttonColor}
      roughness={0.6}
      metalness={0.5}
    />
  );

  return (
    <group>
        {/* ====== 主机壳体 ====== */}
        <RoundedBox args={[0.8, 1.4, 0.5]} radius={0.04} smoothness={4}>
          {bodyMaterial}
        </RoundedBox>

        {/* ====== 正面竖向指令输入槽 ====== */}
        <RoundedBox
          args={[0.12, 0.7, 0.06]}
          radius={0.02}
          smoothness={4}
          position={[0, 0.15, 0.24]}
        >
          {slotMaterial}
        </RoundedBox>

        {/* 输入槽内部深度阴影条 */}
        <RoundedBox
          args={[0.08, 0.6, 0.02]}
          radius={0.01}
          smoothness={4}
          position={[0, 0.15, 0.27]}
        >
          <meshStandardMaterial color="#0f141e" roughness={1} metalness={0} />
        </RoundedBox>

        {/* ====== 顶部状态指示灯 ====== */}
        <mesh position={[0, 0.78, 0]}>
          <sphereGeometry args={[0.06, 32, 32]} />
          {glowMaterial}
        </mesh>

        {/* 指示灯底座环 */}
        <mesh position={[0, 0.72, 0]}>
          <cylinderGeometry args={[0.08, 0.08, 0.03, 32]} />
          {bodyMaterial}
        </mesh>

        {/* ====== 物理按键阵列 ====== */}
        {[0, 1, 2].map((col) =>
          [0, 1].map((row) => (
            <RoundedBox
              key={`btn-${col}-${row}`}
              args={[0.1, 0.1, 0.04]}
              radius={0.015}
              smoothness={4}
              position={[
                -0.15 + col * 0.15,
                -0.35 + row * 0.15,
                0.26,
              ]}
            >
              {buttonMaterial}
            </RoundedBox>
          ))
        )}

        {/* ====== 侧面散热格栅装饰 ====== */}
        {[0, 1, 2].map((i) => (
          <RoundedBox
            key={`vent-r-${i}`}
            args={[0.04, 0.02, 0.35]}
            radius={0.005}
            smoothness={4}
            position={[0.41, 0.3 - i * 0.08, 0]}
          >
            {slotMaterial}
          </RoundedBox>
        ))}

        {[0, 1, 2].map((i) => (
          <RoundedBox
            key={`vent-l-${i}`}
            args={[0.04, 0.02, 0.35]}
            radius={0.005}
            smoothness={4}
            position={[-0.41, 0.3 - i * 0.08, 0]}
          >
            {slotMaterial}
          </RoundedBox>
        ))}

        {/* ====== 底部基座 ====== */}
        <RoundedBox
          args={[0.88, 0.08, 0.56]}
          radius={0.03}
          smoothness={4}
          position={[0, -0.74, 0]}
        >
          <meshStandardMaterial
            color={baseColor}
            roughness={0.8}
            metalness={0.7}
          />
        </RoundedBox>

        {/* ====== 正面铭牌区域 ====== */}
        <RoundedBox
          args={[0.3, 0.06, 0.02]}
          radius={0.01}
          smoothness={4}
          position={[0, -0.18, 0.26]}
        >
          <meshStandardMaterial
            color={plateColor}
            roughness={0.5}
            metalness={0.8}
          />
        </RoundedBox>
    </group>
  );
}
