// 每帧高频读写的可变世界状态，独立于 React/zustand，避免 useFrame 内 setState。
// usePlayerController 每帧写入；CameraRig / PlayerAvatar / 拖尾等系统每帧读取。

export type PlayerWorld = {
  /** 世界坐标（XZ 平面 + 高度 Y） */
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  /** 平面速度（世界单位/秒） */
  speed: number;
  /** 移动朝向（弧度，XZ 平面 atan2） */
  heading: number;
  /** 是否着地 */
  grounded: boolean;
};

export const playerWorld: PlayerWorld = {
  x: 0,
  y: 0,
  z: 0,
  vx: 0,
  vy: 0,
  vz: 0,
  speed: 0,
  heading: 0,
  grounded: true,
};

export function resetPlayerWorld(spawnX: number, spawnZ: number) {
  playerWorld.x = spawnX;
  playerWorld.y = 0;
  playerWorld.z = spawnZ;
  playerWorld.vx = 0;
  playerWorld.vy = 0;
  playerWorld.vz = 0;
  playerWorld.speed = 0;
  playerWorld.heading = 0;
  playerWorld.grounded = true;
}
