// 反射地面：MeshReflectorMaterial 提供 Bruno 式的镜面地板质感，
// 叠加网格纹理（canvas 生成，零外部资源），浅色主题自动切换配色。

import { useMemo } from "react";
import { MeshReflectorMaterial } from "@react-three/drei";
import { RepeatWrapping, SRGBColorSpace, CanvasTexture, LinearFilter } from "three";
import { WORLD_SIZE, palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";

function makeGridTexture(theme: ThemeName): CanvasTexture {
  const size = 256;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext("2d")!;
  const colors = palette[theme];
  context.fillStyle = theme === "light" ? "#f4f8fb" : "#070a12";
  context.fillRect(0, 0, size, size);
  context.strokeStyle = colors.grid;
  context.lineWidth = 2;
  context.strokeRect(0, 0, size, size);
  context.strokeStyle = colors.line;
  context.globalAlpha = 0.35;
  context.lineWidth = 1;
  context.beginPath();
  context.moveTo(size / 2, 0);
  context.lineTo(size / 2, size);
  context.moveTo(0, size / 2);
  context.lineTo(size, size / 2);
  context.stroke();
  const texture = new CanvasTexture(canvas);
  texture.wrapS = RepeatWrapping;
  texture.wrapT = RepeatWrapping;
  texture.repeat.set(WORLD_SIZE / 4, WORLD_SIZE / 4);
  texture.magFilter = LinearFilter;
  texture.colorSpace = SRGBColorSpace;
  return texture;
}

export function Ground({ theme, reflector = true }: { theme: ThemeName; reflector?: boolean }) {
  const gridTexture = useMemo(() => makeGridTexture(theme), [theme]);
  const colors = palette[theme];
  const dark = theme !== "light";

  return (
    <group>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[WORLD_SIZE * 2.4, WORLD_SIZE * 2.4]} />
        {reflector ? (
          <MeshReflectorMaterial
            blur={[0, 0]}
            resolution={1024}
            mixBlur={0}
            mixStrength={dark ? 12 : 4}
            roughness={0.92}
            depthScale={1.1}
            minDepthThreshold={0.4}
            maxDepthThreshold={1.4}
            color={dark ? "#0a0e1a" : "#dfe9f2"}
            metalness={0.55}
            mirror={dark ? 0.55 : 0.25}
            map={gridTexture}
          />
        ) : (
          <meshStandardMaterial color={dark ? "#0a0e1a" : "#dfe9f2"} roughness={0.95} metalness={0.1} map={gridTexture} />
        )}
      </mesh>
      {/* 外圈发光环，呼应 2D 的地平线弧 */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]}>
        <ringGeometry args={[WORLD_SIZE * 0.62, WORLD_SIZE * 0.625, 96]} />
        <meshBasicMaterial color={colors.cyan} transparent opacity={dark ? 0.35 : 0.22} />
      </mesh>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.02, 0]}>
        <ringGeometry args={[WORLD_SIZE * 0.78, WORLD_SIZE * 0.783, 96]} />
        <meshBasicMaterial color={colors.violet} transparent opacity={dark ? 0.2 : 0.12} />
      </mesh>
    </group>
  );
}
