// 氛围层：指数雾 + 星空 + 漂浮微粒 + 背景色，深浅双主题。
// 浅色主题压低星空/微粒存在感，保持信息可读性。

import { Sparkles, Stars } from "@react-three/drei";
import { palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";

export function Atmosphere({ theme, sparkles = true }: { theme: ThemeName; sparkles?: boolean }) {
  const colors = palette[theme];
  const dark = theme !== "light";

  return (
    <group>
      <color attach="background" args={[colors.bg]} />
      <fogExp2 attach="fog" args={[colors.bg, dark ? 0.016 : 0.02]} />
      {dark ? (
        <Stars radius={90} depth={40} count={2200} factor={3.2} saturation={0.4} fade speed={0.6} />
      ) : null}
      {sparkles ? (
        <Sparkles
          count={dark ? 90 : 45}
          scale={[46, 14, 46]}
          position={[0, 6, 0]}
          size={dark ? 2.6 : 1.8}
          speed={0.32}
          color={dark ? colors.cyan : colors.violet}
          opacity={dark ? 0.55 : 0.3}
        />
      ) : null}
    </group>
  );
}
