/**
 * AgentNodeField.tsx — 工业设备模块节点场
 *
 * 替代 NodeField（Platonic solids），使用 11 个工业设备风格的纯静态 Group 模块渲染能力节点。
 * 完全复用 NodeField 的交互契约：toWorld() 坐标系、Zustand store 读写、playerWorld 距离检测、
 * reveal 升起动画、贝塞尔曲线连线、Html DOM 标签。
 *
 * 与 ExperienceScene 中其他系统（LinkBeam/CameraRig/碰撞检测/RevealSystem）完全兼容。
 */

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { Html } from "@react-three/drei";
import { MathUtils, Vector3, CubicBezierCurve3 } from "three";
import type { Group } from "three";
import { useTranslation } from "react-i18next";
import {
  links,
  nodeById,
  nodePalette,
  nodes,
  palette,
  toWorld,
  toWorldRadius,
} from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";
import { playerWorld } from "../world";
import { soundEngine } from "../systems/soundEngine";
import { DataFlowLine } from "./modules/DataFlowLine";

// ─── 模块层导入（纯静态 Group 组件） ──────────────────────
import CoreAgentNode from "./modules/CoreModule";
import { CliConsoleModule } from "./modules/CliModule";
import { GUIMonitor } from "./modules/GuiModule";
import StateStorageArray from "./modules/StateModule";
import { ToolChainModule } from "./modules/ToolsModule";
import { KnowledgeBaseModule } from "./modules/KnowledgeModule";
import { AutomationPipeline } from "./modules/AutomationModule";
import { SafetyGateModule } from "./modules/SafetyModule";
import { ModelInferenceChamber } from "./modules/ModelModule";
import { ReviewInspector } from "./modules/ReviewModule";
import { DeliveryModule } from "./modules/DeliveryModule";

// ═══════════════════════════════════════════════════════════
//  常量配置
// ═══════════════════════════════════════════════════════════

/** 模块基础缩放系数（适配 48 单位世界） */
const MODULE_SCALE = 1.8;
/** near 触发距离（与 NodeField 一致） */
const TRIGGER_DISTANCE = 5.2;
/** 标签显示距离 */
const LABEL_DISTANCE = 8;
/** 节点 resting height */
const NODE_Y = 1.6;
/** scale lerp 速度因子 */
const SCALE_LERP_SPEED = 8;
/** @deprecated 已迁移至 DataFlowLine 管道渲染 */
// const LINK_LINE_WIDTH = 2.4;

// ═══════════════════════════════════════════════════════════
//  节点 ID → 模块组件映射
// ═══════════════════════════════════════════════════════════

const MODULE_COMPONENTS: Record<string, React.ComponentType<{ color: string; dark: boolean }>> = {
  core: CoreAgentNode,
  cli: CliConsoleModule,
  gui: GUIMonitor,
  state: StateStorageArray,
  tools: ToolChainModule,
  knowledge: KnowledgeBaseModule,
  automation: AutomationPipeline,
  safety: SafetyGateModule,
  model: ModelInferenceChamber,
  review: ReviewInspector,
  delivery: DeliveryModule,
};

// ═══════════════════════════════════════════════════════════
//  类型定义
// ═══════════════════════════════════════════════════════════

type LayoutItem = {
  nodeId: string;
  index: number;
  x: number;
  z: number;
  scale: number;
  phase: number;
  spinSpeed: number;
  floatAmp: number;
  colorHex: string;
  labelKey: string;
};

type AgentNodeFieldProps = {
  theme: ThemeName;
  motionEnabled: boolean;
};


// ═══════════════════════════════════════════════════════════
//  主组件
// ═══════════════════════════════════════════════════════════

export function AgentNodeField({ theme, motionEnabled }: AgentNodeFieldProps) {
  const { t } = useTranslation();
  const dark = theme !== "light";
  const colors = palette[theme];
  const nodeColors = nodePalette[theme];

  // ─── Refs ────────────────────────────────────────────────
  const groupRefs = useRef<Array<Group | null>>([]);
  const labelOpacities = useRef<number[]>(nodes.map(() => 0));
  const labelRefs = useRef<Array<HTMLDivElement | null>>([]);
  const nearRef = useRef("");
  const hoverRef = useRef("");

  // ─── Store reads ─────────────────────────────────────────
  const selectedId = useExperienceStore((state) => state.selectedId);
  const hoveredId = useExperienceStore((state) => state.hoveredId);
  const revealProgress = useExperienceStore((state) => state.revealProgress);

  // ─── 布局计算 ────────────────────────────────────────────
  const layout = useMemo<LayoutItem[]>(() => {
    return nodes.map((node, index) => {
      const [x, z] = toWorld(node.x, node.y);
      const baseScale = toWorldRadius(node.radius) * MODULE_SCALE;
      const isCore = node.id === "core";
      const spinSpeed = isCore ? 0.55 : 0.2 + ((index * 37) % 5) * 0.07 * (index % 2 === 0 ? 1 : -1);
      const floatAmp = isCore ? 0.36 : 0.24 + ((index * 23) % 4) * 0.06;
      const colorHex = nodeColors[node.id] ?? colors[node.color];

      return {
        nodeId: node.id,
        index,
        x,
        z,
        scale: baseScale,
        phase: index * 0.83,
        spinSpeed,
        floatAmp,
        colorHex,
        labelKey: node.labelKey,
      };
    });
  }, [theme, colors, nodeColors]);

  // ─── 连线几何（贝塞尔曲线 + per-edge 颜色） ──────────────
  const edges = useMemo(
    () =>
      links.map(([fromId, toId], edgeIndex) => {
        const from = nodeById(fromId);
        const to = nodeById(toId);
        const [fx, fz] = toWorld(from.x, from.y);
        const [tx, tz] = toWorld(to.x, to.y);
        const lift = (a: number, b: number) => 1.1 + Math.abs(a - b) * 0.04;
        const startY = lift(from.radius, to.radius);
        const endY = lift(to.radius, from.radius);

        // 三次贝塞尔：起点 → 控制点1 → 控制点2 → 终点
        // 每条边用不同相位偏移产生形态多样性
        const phase = edgeIndex * 1.618;
        const dist = Math.sqrt((tx - fx) ** 2 + (tz - fz) ** 2);
        const lateralBias = Math.sin(phase) * 0.35;
        // 拱高上限 4.5：俯瞰视角下过高的弧线会冲出画面顶部
        const verticalLift = Math.min(3.0, 0.5 + Math.cos(phase * 0.7) * 0.3);

        const cp1x = fx + (tx - fx) * 0.25 + lateralBias * dist * 0.15;
        const cp1y = startY + verticalLift * dist * 0.12;
        const cp1z = fz + (tz - fz) * 0.25 + Math.cos(phase) * dist * 0.1;

        const cp2x = fx + (tx - fx) * 0.75 - lateralBias * dist * 0.15;
        const cp2y = endY + verticalLift * dist * 0.1;
        const cp2z = fz + (tz - fz) * 0.75 - Math.cos(phase) * dist * 0.1;

        // 采样 24 段平滑曲线
        const curve = new CubicBezierCurve3(
          new Vector3(fx, startY, fz),
          new Vector3(cp1x, cp1y, cp1z),
          new Vector3(cp2x, cp2y, cp2z),
          new Vector3(tx, endY, tz),
        );
        const sampledPts = curve.getPoints(24);
        const points: [number, number, number][] = sampledPts.map((p: Vector3) => [p.x, p.y, p.z]);

        return {
          key: `${fromId}-${toId}`,
          fromId,
          toId,
          points,
          arcLength: curve.getLength(),
          fromColor: nodeColors[fromId] ?? colors[from.color] ?? "#ffffff",
          toColor: nodeColors[toId] ?? colors[to.color] ?? "#ffffff",
        };
      }),
    [nodeColors, colors],
  );

  // ─── Hover / Select 回调 ─────────────────────────────────
  const handleHover = (id: string) => {
    if (id !== hoverRef.current) {
      hoverRef.current = id;
      useExperienceStore.getState().setHovered(id);
      if (id && soundEngine.enabled) soundEngine.play("hover");
      document.body.style.cursor = id ? "pointer" : "";
    }
  };

  const handleSelect = (id: string) => {
    const store = useExperienceStore.getState();
    if (!store.started) return;
    store.select(id);
    store.setCameraMode("focus");
    store.addTrauma(0.25);
    if (soundEngine.enabled) soundEngine.play("burst");
  };

  // ─── 每帧动画循环 ────────────────────────────────────────
  useFrame((state, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    const clock = state.clock.elapsedTime;
    const player = playerWorld;

    let nearestId = "";
    let nearestDistance = Number.POSITIVE_INFINITY;

    for (const item of layout) {
      const group = groupRefs.current[item.index];
      if (!group) continue;

      // Reveal 升起 + 悬浮 + 自旋
      const rise = motionEnabled
        ? MathUtils.clamp(revealProgress * 1.35 - item.index * 0.028, 0, 1)
        : 1;
      const float = motionEnabled
        ? Math.sin(clock * 1.5 + item.phase) * item.floatAmp
        : 0;
      group.position.y = NODE_Y + float - (1 - rise) * 6;
      group.rotation.y = motionEnabled
        ? clock * item.spinSpeed + item.phase
        : item.phase;

      // 选中/悬停放大
      const active = item.nodeId === selectedId || item.nodeId === hoveredId;
      const targetScale = active ? item.scale * 1.35 : item.scale;
      const nextScale =
        group.scale.x + (targetScale - group.scale.x) * (1 - Math.exp(-delta * SCALE_LERP_SPEED));
      group.scale.setScalar(nextScale);

      // 距离检测：nearest + 标签淡入
      const distance = Math.hypot(player.x - item.x, player.z - item.z);
      if (distance < nearestDistance) {
        nearestDistance = distance;
        nearestId = item.nodeId;
      }
      const near = distance < LABEL_DISTANCE;
      const labelTarget = near || active ? 1 : 0;
      const current = labelOpacities.current[item.index];
      const nextOpacity = current + (labelTarget - current) * (1 - Math.exp(-delta * 5));
      labelOpacities.current[item.index] = nextOpacity;
      const labelEl = labelRefs.current[item.index];
      if (labelEl) {
        labelEl.style.opacity = String(MathUtils.clamp(nextOpacity, 0, 1));
      }
    }

    // near 状态只在变化时写 store
    const near = nearestDistance < TRIGGER_DISTANCE ? nearestId : "";
    if (near !== nearRef.current) {
      nearRef.current = near;
      const store = useExperienceStore.getState();
      store.setNear(near);
      if (near) {
        store.markVisited(near);
        if (soundEngine.enabled) soundEngine.play("near");
      }
    }
  });

  // ─── 渲染 ────────────────────────────────────────────────
  return (
    <group>
      {/* ===== 11 个工业设备模块节点 ===== */}
      {layout.map((item) => {
        const ModuleComponent = MODULE_COMPONENTS[item.nodeId];
        if (!ModuleComponent) return null;

        return (
          <group
            key={item.nodeId}
            ref={(value) => {
              groupRefs.current[item.index] = value;
            }}
            position={[item.x, NODE_Y, item.z]}
            scale={item.scale}
          >
            <group
              onPointerOver={(e) => {
                e.stopPropagation();
                handleHover(item.nodeId);
              }}
              onPointerOut={(e) => {
                e.stopPropagation();
                handleHover("");
              }}
              onClick={(e) => {
                e.stopPropagation();
                handleSelect(item.nodeId);
              }}
            >
              <ModuleComponent color={item.colorHex} dark={dark} />
            </group>

            {/* DOM 标签 */}
            <Html
              position={[0, 2.2, 0]}
              center
              distanceFactor={LABEL_DISTANCE}
              style={{ pointerEvents: "none" }}
            >
              <div
                ref={(value) => {
                  labelRefs.current[item.index] = value;
                }}
                style={{
                  color: colors.text,
                  fontSize: "11px",
                  fontFamily: '"JetBrains Mono", monospace',
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                  whiteSpace: "nowrap",
                  textShadow: `0 0 8px ${item.colorHex}`,
                  opacity: 0,
                  userSelect: "none",
                }}
              >
                {t(item.labelKey)}
              </div>
            </Html>
          </group>
        );
      })}

      {/* ===== 连线层（渐变管道 + 流光脉冲） ===== */}
      {edges.map((edge, i) => (
        <DataFlowLine
          key={edge.key}
          points={edge.points}
          fromColor={edge.fromColor}
          toColor={edge.toColor}
          dark={dark}
          edgeIndex={i}
          arcLength={edge.arcLength}
        />
      ))}
    </group>
  );
}
