import * as THREE from 'three';
import { RoundedBox } from '@react-three/drei';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * ReviewInspector - 四通道质检检测仪
 * 业务能力：review审查校验，多维度检测判断
 */
export function ReviewInspector({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Derive tinted light-mode colors from the node's palette color
  const shellBase = new THREE.Color(color);
  const metalColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const glassColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const ventColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const footColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.25).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const metalColor = dark ? darkShell('#2a2e34', color) : metalColorLight;
  const glassColor = dark ? darkShell('#3a3e44', color) : glassColorLight;
  const ventColor = dark ? darkShell('#1a1e24', color, 0.25, 0.12) : ventColorLight;
  const footColor = dark ? darkShell('#0e1218', color, 0.25, 0.12) : footColorLight;

  const metalMaterial = (
    <meshStandardMaterial
      color={metalColor}
      roughness={0.7}
      metalness={0.8}
    />
  );

  const glassMaterial = (
    <meshStandardMaterial
      color={glassColor}
      roughness={0.3}
      metalness={0.2}
      transparent
      opacity={0.6}
    />
  );

  const emissiveMaterial = (
    <meshStandardMaterial
      color={color}
      emissive={color}
      emissiveIntensity={2 * emissiveScale}
      roughness={0.4}
      metalness={0.3}
    />
  );

  // 单个采样通道组件
  const SamplingChannel = ({ position, rotation }: { position: [number, number, number]; rotation?: [number, number, number] }) => (
    <group position={position} rotation={rotation}>
      <mesh castShadow receiveShadow>
        <cylinderGeometry args={[0.08, 0.08, 0.35, 16]} />
        {metalMaterial}
      </mesh>
      <mesh position={[0, 0.18, 0]} castShadow>
        <torusGeometry args={[0.06, 0.015, 8, 16]} />
        {glassMaterial}
      </mesh>
      <mesh position={[0, 0.12, 0]}>
        <cylinderGeometry args={[0.03, 0.03, 0.05, 12]} />
        {emissiveMaterial}
      </mesh>
    </group>
  );

  return (
    <group>
        {/* ===== 主体方盒检测仪 ===== */}
        <RoundedBox args={[0.7, 0.5, 0.7]} radius={0.04} smoothness={4} castShadow receiveShadow>
          {metalMaterial}
        </RoundedBox>

        {/* 主体顶部盖板 */}
        <RoundedBox args={[0.5, 0.04, 0.5]} radius={0.02} smoothness={4} position={[0, 0.27, 0]} castShadow>
          {glassMaterial}
        </RoundedBox>

        {/* ===== 中心判断单元 ===== */}
        <RoundedBox args={[0.2, 0.2, 0.2]} radius={0.02} smoothness={4} position={[0, 0.05, 0]} castShadow>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.5 * emissiveScale}
            roughness={0.5}
            metalness={0.6}
          />
        </RoundedBox>

        {/* ===== 四个方向采样通道 ===== */}
        <SamplingChannel position={[0, 0, 0.45]} rotation={[Math.PI / 2, 0, 0]} />
        <SamplingChannel position={[0, 0, -0.45]} rotation={[-Math.PI / 2, 0, 0]} />
        <SamplingChannel position={[-0.45, 0, 0]} rotation={[0, 0, Math.PI / 2]} />
        <SamplingChannel position={[0.45, 0, 0]} rotation={[0, 0, -Math.PI / 2]} />

        {/* ===== 正面状态指示灯 ===== */}
        <mesh position={[0, 0.1, 0.36]} castShadow>
          <sphereGeometry args={[0.045, 16, 16]} />
          {emissiveMaterial}
        </mesh>

        <mesh position={[0, 0.1, 0.355]} castShadow>
          <torusGeometry args={[0.05, 0.008, 8, 16]} />
          {metalMaterial}
        </mesh>

        {/* ===== 底部安装基座 ===== */}
        <RoundedBox args={[0.6, 0.06, 0.6]} radius={0.02} smoothness={4} position={[0, -0.28, 0]} castShadow receiveShadow>
          {metalMaterial}
        </RoundedBox>

        {/* 基座四角防滑垫 */}
        {[[-0.22, -0.32, -0.22], [0.22, -0.32, -0.22], [-0.22, -0.32, 0.22], [0.22, -0.32, 0.22]].map((pos, i) => (
          <mesh key={i} position={pos as [number, number, number]} castShadow>
            <cylinderGeometry args={[0.03, 0.035, 0.03, 12]} />
            <meshStandardMaterial color={footColor} roughness={0.9} metalness={0.1} />
          </mesh>
        ))}

        {/* ===== 侧面散热格栅 ===== */}
        {[-0.1, 0, 0.1].map((yOffset, i) => (
          <mesh key={`vent-l-${i}`} position={[-0.355, yOffset, 0]} castShadow>
            <boxGeometry args={[0.01, 0.025, 0.35]} />
            <meshStandardMaterial color={ventColor} roughness={0.8} metalness={0.7} />
          </mesh>
        ))}
        {[-0.1, 0, 0.1].map((yOffset, i) => (
          <mesh key={`vent-r-${i}`} position={[0.355, yOffset, 0]} castShadow>
            <boxGeometry args={[0.01, 0.025, 0.35]} />
            <meshStandardMaterial color={ventColor} roughness={0.8} metalness={0.7} />
          </mesh>
        ))}
    </group>
  );
}
