// 相机绑定：reveal → follow / focus / overview 三态，全程 maath damp3 阻尼插值。
// 无关键帧动画——一切相机运动 = 每帧向当前模式的目标位姿插值（Bruno Simon 核心手法）。
// 震屏：trauma² 驱动的高频抖动叠加在最终位置。

import { useMemo, useRef } from "react";
import { useFrame, useThree } from "@react-three/fiber";
import { easing } from "maath";
import { Vector3 } from "three";
import { playerWorld } from "../world";
import { useExperienceStore } from "../store";
import { nodes, toWorld, toWorldRadius } from "../../experience/experienceData";

const FOLLOW_OFFSET = new Vector3(0, 5.2, 8.5);
const FOLLOW_LOOK_AHEAD = 2.2;
// 俯瞰需覆盖 48×48 世界（节点分布 ±19.2）：fov42 下高度 50 → 垂直半覆盖 ≈23.2
const OVERVIEW_POSITION = new Vector3(0, 50, 34);
const REVEAL_POSITION = new Vector3(0, 58, 52);

const tmpTarget = new Vector3();
const tmpLook = new Vector3();
const tmpFocus = new Vector3();

export function CameraRig() {
  const camera = useThree((state) => state.camera);
  const lookTarget = useRef(new Vector3(0, 1, 0));
  const shakeSeed = useRef(Math.random() * 100);
  const fovBase = useRef(42);
  const trauma = useExperienceStore((state) => state.trauma);
  const setTrauma = useExperienceStore((state) => state.setTrauma);

  const focusPoints = useMemo(() => {
    const map = new Map<string, { x: number; z: number; radius: number }>();
    for (const node of nodes) {
      const [x, z] = toWorld(node.x, node.y);
      map.set(node.id, { x, z, radius: toWorldRadius(node.radius) });
    }
    return map;
  }, []);

  useFrame((state, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    const { cameraMode, selectedId, started, revealProgress } = useExperienceStore.getState();
    const player = playerWorld;
    const speedNorm = Math.min(1, player.speed / 12);

    // 目标位置
    if (!started || cameraMode === "reveal") {
      tmpTarget.copy(REVEAL_POSITION);
      tmpLook.set(0, 0, 0);
    } else if (cameraMode === "overview") {
      tmpTarget.copy(OVERVIEW_POSITION);
      tmpLook.set(0, 0, 0);
    } else if (cameraMode === "focus" && selectedId) {
      const focus = focusPoints.get(selectedId);
      if (focus) {
        tmpFocus.set(focus.x, 1.2, focus.z);
        // 从玩家方向看向节点，避免穿模
        const awayX = player.x - focus.x;
        const awayZ = player.z - focus.z;
        const awayLength = Math.hypot(awayX, awayZ) || 1;
        const distance = 6.5 + focus.radius * 1.6;
        tmpTarget.set(focus.x + (awayX / awayLength) * distance, 4.4, focus.z + (awayZ / awayLength) * distance);
        tmpLook.copy(tmpFocus);
      } else {
        tmpTarget.set(player.x + FOLLOW_OFFSET.x, player.y + FOLLOW_OFFSET.y, player.z + FOLLOW_OFFSET.z);
        tmpLook.set(player.x, player.y + 1, player.z);
      }
    } else {
      // follow：带速度前瞻，速度越快相机越抬、越退
      const aheadX = Math.sin(player.heading) * FOLLOW_LOOK_AHEAD * speedNorm;
      const aheadZ = Math.cos(player.heading) * FOLLOW_LOOK_AHEAD * speedNorm;
      tmpTarget.set(
        player.x + FOLLOW_OFFSET.x * (1 + speedNorm * 0.12),
        player.y + FOLLOW_OFFSET.y * (1 + speedNorm * 0.08),
        player.z + FOLLOW_OFFSET.z * (1 + speedNorm * 0.12),
      );
      tmpLook.set(player.x + aheadX, player.y + 1, player.z + aheadZ);
    }

    // reveal 期间把起点拉到玩家头顶上方再落下，配合 revealProgress
    if (started && revealProgress < 1) {
      const lift = (1 - revealProgress) * 22;
      tmpTarget.y += lift;
    }

    const smoothTime = cameraMode === "focus" ? 0.5 : 0.42;
    easing.damp3(camera.position, tmpTarget, smoothTime, delta);
    easing.damp3(lookTarget.current, tmpLook, 0.35, delta);

    // 震屏：trauma² × 高频正弦
    const shake = trauma * trauma;
    if (shake > 0.0001) {
      const time = state.clock.elapsedTime * 34 + shakeSeed.current;
      camera.position.x += Math.sin(time * 1.1) * shake * 0.22;
      camera.position.y += Math.cos(time * 1.7) * shake * 0.16;
      setTrauma(trauma - delta * 1.35);
    }

    camera.lookAt(lookTarget.current);

    // 速度感应 FOV：42 → 47
    const perspective = camera as unknown as { fov: number; updateProjectionMatrix: () => void; isPerspectiveCamera?: boolean };
    if (perspective.isPerspectiveCamera) {
      const targetFov = fovBase.current + speedNorm * 5;
      const next = perspective.fov + (targetFov - perspective.fov) * (1 - Math.exp(-delta * 4));
      if (Math.abs(next - perspective.fov) > 0.01) {
        perspective.fov = next;
        perspective.updateProjectionMatrix();
      }
    }
  });

  return null;
}
