// 冲击波光环：揭幕/选中时的地面扩散环 + 一圈上扬尘埃粒子。
// 两个子效果：
//   (a) ShockRing — 平面 ring mesh 贴地（rotation -PI/2, y=0.05），触发时 scale 0.5 → 大半径、opacity 0.8 → 0。
//   (b) DustRing — 约 60 个尘埃粒子沿环切线向外+向上抛洒，Points 单 draw call，AdditiveBlending 短寿命淡出。
// 触发源：reveal（started 由 false→true，世界中心大环）与 select（selectedId 变化，节点处小环+尘埃）。
// 固定容量池（最多并存 4 个 ring + 240 尘埃），模块级 Vector3/Color 复用，零每帧分配。
// motionEnabled=false 时 reveal 环瞬时完成（scale 直接到最大、opacity 快速归零）。

import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color, DoubleSide, MathUtils } from "three";
import type { Mesh, MeshBasicMaterial } from "three";
import { nodes, palette, toWorld } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";

// ---------------------------------------------------------------------------
// 常量
// ---------------------------------------------------------------------------

/** 同时并存的冲击波环上限 */
const MAX_RINGS = 4;
/** 单次 select 触发的尘埃数（reveal 不喷尘埃） */
const DUST_PER_BURST = 60;
/** 尘埃池总容量（支持最多 4 次 select 并存） */
const MAX_DUST = DUST_PER_BURST * MAX_RINGS;

/** 环寿命（秒） */
const RING_LIFETIME = 1.4;
/** 尘埃寿命（秒） */
const DUST_LIFETIME = 0.85;

/** reveal 环（世界中心，大范围） */
const REVEAL_RING = {
  startScale: 0.5,
  endScale: 22,
  opacity: 0.8,
};
/** select 环（节点处，小范围） */
const SELECT_RING = {
  startScale: 0.5,
  endScale: 4.2,
  opacity: 0.85,
};

// ---------------------------------------------------------------------------
// 模块级复用对象（useFrame / 触发器内零分配）
// ---------------------------------------------------------------------------

const tmpColor = new Color();

// ---------------------------------------------------------------------------
// 类型
// ---------------------------------------------------------------------------

type RingSlot = {
  active: boolean;
  age: number;
  startScale: number;
  endScale: number;
  baseOpacity: number;
  color: Color;
};

type ShockwaveRingProps = {
  theme: ThemeName;
  motionEnabled: boolean;
};

// ---------------------------------------------------------------------------
// 组件
// ---------------------------------------------------------------------------

export function ShockwaveRing({ theme, motionEnabled }: ShockwaveRingProps) {
  const colors = palette[theme];

  // ---- ShockRing 池（4 个 mesh，slots 记录动画状态） ----
  const ringSlots = useMemo<Array<RingSlot>>(
    () =>
      Array.from({ length: MAX_RINGS }, () => ({
        active: false,
        age: 0,
        startScale: 0.5,
        endScale: 1,
        baseOpacity: 0.8,
        color: new Color("#ffffff"),
      })),
    [],
  );
  const ringMeshRefs = useRef<Array<Mesh | null>>([]);
  const ringMaterialRefs = useRef<Array<MeshBasicMaterial | null>>([]);
  const ringCursor = useRef(0);

  // ---- DustRing 池（Float32Array 环形缓冲，Points 单 draw call） ----
  const dustPositions = useMemo(() => {
    const buffer = new Float32Array(MAX_DUST * 3);
    for (let i = 0; i < MAX_DUST; i += 1) {
      buffer[i * 3 + 1] = -100; // 初始全部藏到地下，避免首帧闪烁
    }
    return buffer;
  }, []);
  const dustVelocities = useMemo(() => new Float32Array(MAX_DUST * 3), []);
  const dustAges = useMemo(() => new Float32Array(MAX_DUST).fill(DUST_LIFETIME + 1), []);
  const dustColors = useMemo(() => new Float32Array(MAX_DUST * 3), []);
  const dustCursor = useRef(0);

  const dustGeometry = useMemo(() => {
    const buffer = new BufferGeometry();
    buffer.setAttribute("position", new BufferAttribute(dustPositions, 3));
    buffer.setAttribute("color", new BufferAttribute(dustColors, 3));
    return buffer;
  }, [dustPositions, dustColors]);

  // ---------------------------------------------------------------------------
  // 触发器（写池，非每帧路径，允许做简单写入；不分配新对象）
  // ---------------------------------------------------------------------------

  /** 激活一个 ring slot；motionEnabled=false 时由调用方传 startScale=endScale、opacity=0 实现瞬时完成 */
  const triggerRing = (x: number, z: number, startScale: number, endScale: number, baseOpacity: number, colorHex: string) => {
    const index = ringCursor.current;
    ringCursor.current = (ringCursor.current + 1) % MAX_RINGS;
    const slot = ringSlots[index];
    slot.active = true;
    slot.age = 0;
    slot.startScale = startScale;
    slot.endScale = endScale;
    slot.baseOpacity = baseOpacity;
    slot.color.set(colorHex);
    const mesh = ringMeshRefs.current[index];
    if (mesh) {
      mesh.visible = true;
      mesh.position.set(x, 0.05, z);
      mesh.scale.set(startScale, startScale, startScale);
    }
  };

  /** 在 (x, z) 处喷一圈 60 个尘埃 */
  const triggerDust = (x: number, z: number, colorHex: string) => {
    tmpColor.set(colorHex);
    for (let i = 0; i < DUST_PER_BURST; i += 1) {
      const slot = dustCursor.current;
      dustCursor.current = (dustCursor.current + 1) % MAX_DUST;
      // 沿环切线均匀分布 + 少量随机扰动，方向 = 径向向外 + 切向偏离 + 向上抛
      const angle = (Math.PI * 2 * i) / DUST_PER_BURST + Math.random() * 0.22;
      const tangent = angle + Math.PI / 2;
      const radialSpeed = 1.6 + Math.random() * 1.4;
      const tangentSpeed = (Math.random() - 0.5) * 1.4;
      const upSpeed = 2.6 + Math.random() * 2.4;
      const base = slot * 3;
      dustPositions[base] = x;
      dustPositions[base + 1] = 0.08;
      dustPositions[base + 2] = z;
      dustVelocities[base] = Math.cos(angle) * radialSpeed + Math.cos(tangent) * tangentSpeed;
      dustVelocities[base + 1] = upSpeed;
      dustVelocities[base + 2] = Math.sin(angle) * radialSpeed + Math.sin(tangent) * tangentSpeed;
      dustAges[slot] = 0;
      dustColors[base] = tmpColor.r;
      dustColors[base + 1] = tmpColor.g;
      dustColors[base + 2] = tmpColor.b;
    }
  };

  // 用 ref 持有最新的触发器，供订阅回调（闭包可能陈旧）调用
  const triggerRef = useRef({ triggerRing, triggerDust, colors, motionEnabled });
  triggerRef.current = { triggerRing, triggerDust, colors, motionEnabled };

  // ---------------------------------------------------------------------------
  // 监听 reveal：started 由 false → true（用 subscribe 而非 hook，避免每次渲染重订阅）
  // ---------------------------------------------------------------------------
  useEffect(() => {
    let prevStarted = useExperienceStore.getState().started;
    const unsubscribe = useExperienceStore.subscribe((state) => {
      const started = state.started;
      if (started && !prevStarted) {
        const { triggerRing: fire, colors: c, motionEnabled: motion } = triggerRef.current;
        if (motion) {
          fire(0, 0, REVEAL_RING.startScale, REVEAL_RING.endScale, REVEAL_RING.opacity, c.cyan);
        } else {
          // motionEnabled=false：瞬时完成（scale 直接到最大、opacity 立即归零）
          fire(0, 0, REVEAL_RING.endScale, REVEAL_RING.endScale, 0, c.cyan);
        }
      }
      prevStarted = started;
    });
    return unsubscribe;
  }, []);

  // ---------------------------------------------------------------------------
  // 监听 select：selectedId 变化 → 在节点 toWorld 处触发小环 + 尘埃
  // （参考 SelectionBurst 的 useEffect 模式）
  // ---------------------------------------------------------------------------
  const selectedId = useExperienceStore((state) => state.selectedId);
  const lastSelected = useRef("");
  useEffect(() => {
    if (!selectedId || selectedId === lastSelected.current) return;
    lastSelected.current = selectedId;
    const node = nodes.find((item) => item.id === selectedId);
    if (!node) return;
    const [x, z] = toWorld(node.x, node.y);
    const { triggerRing: fireRing, triggerDust: fireDust, colors: c } = triggerRef.current;
    const hex = c[node.color];
    fireRing(x, z, SELECT_RING.startScale, SELECT_RING.endScale, SELECT_RING.opacity, hex);
    fireDust(x, z, hex);
  }, [selectedId]);

  // ---------------------------------------------------------------------------
  // 每帧积分 + 衰减（零分配、零 setState）
  // ---------------------------------------------------------------------------
  useFrame((_, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);

    // ---- ShockRing：scale 扩散 + opacity 衰减 ----
    for (let i = 0; i < MAX_RINGS; i += 1) {
      const slot = ringSlots[i];
      const mesh = ringMeshRefs.current[i];
      const material = ringMaterialRefs.current[i];
      if (!mesh || !material) continue;
      if (!slot.active) {
        if (mesh.visible) {
          mesh.visible = false;
        }
        continue;
      }
      slot.age += delta;
      const t = Math.min(1, slot.age / RING_LIFETIME);
      // easeOutCubic：扩散先快后慢
      const eased = 1 - (1 - t) * (1 - t) * (1 - t);
      const scale = MathUtils.lerp(slot.startScale, slot.endScale, eased);
      mesh.scale.set(scale, scale, scale);
      material.opacity = slot.baseOpacity * (1 - t);
      material.color.copy(slot.color);
      if (t >= 1) {
        slot.active = false;
        mesh.visible = false;
      }
    }

    // ---- DustRing：积分 + 重力 + 亮度平方衰减 ----
    let dustDirty = false;
    for (let i = 0; i < MAX_DUST; i += 1) {
      if (dustAges[i] > DUST_LIFETIME) {
        if (dustPositions[i * 3 + 1] > -50) {
          dustPositions[i * 3 + 1] = -100; // 死亡的尘埃藏到地下
          dustDirty = true;
        }
        continue;
      }
      dustAges[i] += delta;
      const base = i * 3;
      dustVelocities[base + 1] -= 10 * delta; // 重力
      dustPositions[base] += dustVelocities[base] * delta;
      dustPositions[base + 1] += dustVelocities[base + 1] * delta;
      dustPositions[base + 2] += dustVelocities[base + 2] * delta;
      const fade = Math.max(0, 1 - dustAges[i] / DUST_LIFETIME);
      const brightness = fade * fade;
      const colorAttr = dustGeometry.getAttribute("color") as BufferAttribute;
      colorAttr.setXYZ(i, dustColors[base] * brightness, dustColors[base + 1] * brightness, dustColors[base + 2] * brightness);
      dustDirty = true;
    }
    if (dustDirty) {
      dustGeometry.getAttribute("position").needsUpdate = true;
      dustGeometry.getAttribute("color").needsUpdate = true;
    }
  });

  // ---------------------------------------------------------------------------
  // 渲染
  // ---------------------------------------------------------------------------

  // 浅色主题压小粒子尺寸保可读，深色主题高发光
  const dustSize = theme === "light" ? 0.1 : 0.14;

  return (
    <>
      {/* ShockRing 池：4 个平面 ring mesh 贴地（rotation -PI/2, y=0.05） */}
      {ringSlots.map((_, index) => (
        <mesh
          // 池内索引稳定，使用索引作为 key 安全
          key={`shock-ring-${index}`}
          ref={(mesh) => {
            ringMeshRefs.current[index] = mesh;
          }}
          position={[0, 0.05, 0]}
          rotation={[-Math.PI / 2, 0, 0]}
          visible={false}
          frustumCulled={false}
        >
          <ringGeometry args={[0.92, 1, 64]} />
          <meshBasicMaterial
            ref={(material) => {
              ringMaterialRefs.current[index] = material;
            }}
            transparent
            opacity={0}
            blending={AdditiveBlending}
            depthWrite={false}
            side={DoubleSide}
          />
        </mesh>
      ))}

      {/* DustRing：Points 单 draw call */}
      <points geometry={dustGeometry} frustumCulled={false}>
        <pointsMaterial
          size={dustSize}
          vertexColors
          transparent
          blending={AdditiveBlending}
          depthWrite={false}
          sizeAttenuation
        />
      </points>
    </>
  );
}
