// 运动学玩家控制器（Kinematic Character Controller）。
// WASD/方向键移动，Shift 加速，Space 跳跃；节点球形软推出；世界边界软墙。
// 每帧只写 playerWorld 可变对象，不触发任何 React 状态更新。

import { useEffect, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { nodes, toWorld, toWorldRadius, WORLD_SIZE } from "../../experience/experienceData";
import { playerWorld } from "../world";
import { useExperienceStore } from "../store";
import { soundEngine } from "./soundEngine";

const WALK_SPEED = 7; // 世界单位/秒
const RUN_MULTIPLIER = 1.75;
const GRAVITY = -20;
const JUMP_VELOCITY = 7.5;
const AVATAR_RADIUS = 0.55;
const WALL_LIMIT = WORLD_SIZE / 2 - 1.2;
const WALL_SOFTNESS = 2.4;

// 节点碰撞体（XZ 平面圆柱 + 软推出），模块级一次性构建，零每帧分配
const colliders = nodes.map((node) => {
  const [x, z] = toWorld(node.x, node.y);
  return { x, z, radius: toWorldRadius(node.radius) + AVATAR_RADIUS + 0.25 };
});

export function usePlayerController() {
  const keysRef = useRef(new Set<string>());
  const started = useExperienceStore((state) => state.started);

  useEffect(() => {
    const down = (event: KeyboardEvent) => {
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "KeyW", "KeyA", "KeyS", "KeyD", "Space"].includes(event.code)) {
        event.preventDefault();
      }
      keysRef.current.add(event.code);
    };
    const up = (event: KeyboardEvent) => keysRef.current.delete(event.code);
    const blur = () => keysRef.current.clear();
    window.addEventListener("keydown", down);
    window.addEventListener("keyup", up);
    window.addEventListener("blur", blur);
    return () => {
      window.removeEventListener("keydown", down);
      window.removeEventListener("keyup", up);
      window.removeEventListener("blur", blur);
    };
  }, []);

  useFrame((_, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05); // 防止切后台后大步长穿透
    const keys = keysRef.current;
    const player = playerWorld;

    let ix = 0;
    let iz = 0;
    if (started) {
      if (keys.has("KeyA") || keys.has("ArrowLeft")) ix -= 1;
      if (keys.has("KeyD") || keys.has("ArrowRight")) ix += 1;
      if (keys.has("KeyW") || keys.has("ArrowUp")) iz -= 1;
      if (keys.has("KeyS") || keys.has("ArrowDown")) iz += 1;
    }
    const hasInput = ix !== 0 || iz !== 0;
    if (hasInput) {
      const length = Math.hypot(ix, iz);
      ix /= length;
      iz /= length;
    }
    const running = keys.has("ShiftLeft") || keys.has("ShiftRight");
    const targetSpeed = hasInput ? WALK_SPEED * (running ? RUN_MULTIPLIER : 1) : 0;

    // 指数趋近目标速度（Bruno 式阻尼，一切动画 = 向状态目标插值）
    const accel = 1 - Math.exp(-delta * 10);
    player.vx += (ix * targetSpeed - player.vx) * accel;
    player.vz += (iz * targetSpeed - player.vz) * accel;

    // 跳跃与重力
    if (started && player.grounded && keys.has("Space")) {
      player.vy = JUMP_VELOCITY;
      player.grounded = false;
      if (soundEngine.enabled) soundEngine.play("jump");
    }
    if (!player.grounded) {
      player.vy += GRAVITY * delta;
    }
    player.y += player.vy * delta;
    if (player.y <= 0) {
      player.y = 0;
      player.vy = 0;
      player.grounded = true;
    }

    player.x += player.vx * delta;
    player.z += player.vz * delta;

    // 节点软推出（圆柱碰撞）
    for (const collider of colliders) {
      const dx = player.x - collider.x;
      const dz = player.z - collider.z;
      const distance = Math.hypot(dx, dz);
      if (distance < collider.radius && distance > 0.0001) {
        const push = collider.radius - distance;
        player.x += (dx / distance) * push;
        player.z += (dz / distance) * push;
      }
    }

    // 世界边界软墙
    if (player.x > WALL_LIMIT) player.x = WALL_LIMIT - Math.min(WALL_SOFTNESS, player.x - WALL_LIMIT) * 0.5;
    if (player.x < -WALL_LIMIT) player.x = -WALL_LIMIT + Math.min(WALL_SOFTNESS, -WALL_LIMIT - player.x) * 0.5;
    if (player.z > WALL_LIMIT) player.z = WALL_LIMIT - Math.min(WALL_SOFTNESS, player.z - WALL_LIMIT) * 0.5;
    if (player.z < -WALL_LIMIT) player.z = -WALL_LIMIT + Math.min(WALL_SOFTNESS, -WALL_LIMIT - player.z) * 0.5;

    player.speed = Math.hypot(player.vx, player.vz);
    if (player.speed > 0.5) player.heading = Math.atan2(player.vx, player.vz);
  });
}
