import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * ModelInferenceChamber - 大模型黑盒推理腔体模块
 * 业务能力映射：大模型推理引擎
 */
export function ModelInferenceChamber({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;
  const emissiveColor = new THREE.Color(color);
  const glassColor = new THREE.Color(color);
  // Light-mode metal tinted from node palette color instead of neutral gray
  const metalColorLight = new THREE.Color(color).lerp(new THREE.Color('#ffffff'), 0.5);
  // 暗色外壳注入节点色相，避免与深色背景同化
  const metalColor = dark ? new THREE.Color(darkShell('#1a2530', color)) : metalColorLight;

  return (
    <group>
        {/* === 主腔体外层磨砂玻璃壳 === */}
        <RoundedBox args={[1.0, 0.9, 0.8]} radius={0.25} smoothness={4}>
          <meshStandardMaterial
            color={glassColor}
            transparent
            opacity={0.35}
            roughness={0.8}
            metalness={0.1}
            emissive={emissiveColor}
            emissiveIntensity={0.15 * emissiveScale}
          />
        </RoundedBox>

        {/* 内层核心光晕 */}
        <RoundedBox args={[0.7, 0.6, 0.55]} radius={0.2} smoothness={4}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.2}
            roughness={0.9}
            metalness={0.0}
            emissive={emissiveColor}
            emissiveIntensity={0.6 * emissiveScale}
          />
        </RoundedBox>

        {/* 腔体顶部装饰环 */}
        <mesh position={[0, 0.46, 0]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.25, 0.02, 16, 32]} />
          <meshStandardMaterial
            color={metalColor}
            roughness={0.4}
            metalness={0.8}
            emissive={emissiveColor}
            emissiveIntensity={0.3 * emissiveScale}
          />
        </mesh>

        {/* 腔体底部基座环 */}
        <mesh position={[0, -0.46, 0]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.3, 0.025, 16, 32]} />
          <meshStandardMaterial
            color={metalColor}
            roughness={0.4}
            metalness={0.8}
          />
        </mesh>

        {/* === 左侧数据输入端口 === */}
        <group position={[-0.65, 0, 0]}>
          <mesh rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.12, 0.12, 0.35, 24]} />
            <meshStandardMaterial
              color={metalColor}
              roughness={0.35}
              metalness={0.85}
            />
          </mesh>
          <mesh position={[-0.18, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.16, 0.16, 0.04, 24]} />
            <meshStandardMaterial
              color={metalColor}
              roughness={0.3}
              metalness={0.9}
              emissive={emissiveColor}
              emissiveIntensity={0.2 * emissiveScale}
            />
          </mesh>
          <mesh position={[-0.2, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <torusGeometry args={[0.1, 0.012, 12, 24]} />
            <meshStandardMaterial
              color={color}
              emissive={emissiveColor}
              emissiveIntensity={0.8 * emissiveScale}
            />
          </mesh>
        </group>

        {/* === 右侧数据输出端口 === */}
        <group position={[0.65, 0, 0]}>
          <mesh rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.12, 0.12, 0.35, 24]} />
            <meshStandardMaterial
              color={metalColor}
              roughness={0.35}
              metalness={0.85}
            />
          </mesh>
          <mesh position={[0.18, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <cylinderGeometry args={[0.16, 0.16, 0.04, 24]} />
            <meshStandardMaterial
              color={metalColor}
              roughness={0.3}
              metalness={0.9}
              emissive={emissiveColor}
              emissiveIntensity={0.2 * emissiveScale}
            />
          </mesh>
          <mesh position={[0.2, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <torusGeometry args={[0.1, 0.012, 12, 24]} />
            <meshStandardMaterial
              color={color}
              emissive={emissiveColor}
              emissiveIntensity={0.8 * emissiveScale}
            />
          </mesh>
        </group>

        {/* === 腔体表面加强筋 === */}
        <mesh position={[0, 0.15, 0.41]}>
          <boxGeometry args={[0.6, 0.03, 0.02]} />
          <meshStandardMaterial color={metalColor} roughness={0.4} metalness={0.8} />
        </mesh>
        <mesh position={[0, -0.15, 0.41]}>
          <boxGeometry args={[0.6, 0.03, 0.02]} />
          <meshStandardMaterial color={metalColor} roughness={0.4} metalness={0.8} />
        </mesh>
        <mesh position={[0, 0.15, -0.41]}>
          <boxGeometry args={[0.6, 0.03, 0.02]} />
          <meshStandardMaterial color={metalColor} roughness={0.4} metalness={0.8} />
        </mesh>
        <mesh position={[0, -0.15, -0.41]}>
          <boxGeometry args={[0.6, 0.03, 0.02]} />
          <meshStandardMaterial color={metalColor} roughness={0.4} metalness={0.8} />
        </mesh>

        {/* 中央状态指示点 */}
        <mesh position={[0, 0, 0.42]}>
          <sphereGeometry args={[0.035, 16, 16]} />
          <meshStandardMaterial
            color="#ffffff"
            emissive={emissiveColor}
            emissiveIntensity={1.2 * emissiveScale}
          />
        </mesh>
    </group>
  );
}
