// 全息氛围层：核心节点上方的旋转全息数据环 + 周期性竖直扫描平面 + 世界边缘四根神光柱。
// 性能要点：所有几何/材质在 useMemo 或模块级创建一次；useFrame 内只改 rotation/position/opacity 标量，
// 零分配（无 new Vector3/Color/对象字面量）；revealProgress 经 getState 低频读取，不进 React 状态。

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, DoubleSide } from "three";
import type { Group, Mesh, MeshBasicMaterial } from "three";
import { nodeById, palette, toWorld, WORLD_SIZE } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";

// 三环参数：高度 / 半径 / 角速度（rad/s，含方向）/ 浮动相位
const RING_HEIGHTS = [2.2, 3.0, 3.8] as const;
const RING_RADII = [2.6, 3.4, 4.2] as const;
const RING_SPEEDS = [0.55, -0.38, 0.26] as const;
const RING_PHASES = [0, 2.1, 4.2] as const;
const RING_TUBE = 0.035;
const RING_FLOAT_AMP = 0.16;
const RING_FLOAT_SPEED = 0.7;

// 扫描墙：横向往返周期（秒）
const SCAN_PERIOD = 9;

// 神光柱
const GODRAY_OFFSET = WORLD_SIZE * 0.42;
const GODRAY_RADIUS = 0.4;
const GODRAY_HEIGHT = 30;
const GODRAY_PULSE_SPEED = 0.5;

type HoloLayerProps = {
  theme: ThemeName;
  motionEnabled: boolean;
};

export function HoloLayer({ theme, motionEnabled }: HoloLayerProps) {
  const colors = palette[theme];
  const dark = theme !== "light";

  // 核心节点世界坐标（恒定，模块外计算无意义，useMemo 一次）
  const corePosition = useMemo(() => {
    const core = nodeById("core");
    const [x, z] = toWorld(core.x, core.y);
    return [x, z] as const;
  }, []);

  const ringColors = useMemo(() => [colors.cyan, colors.violet, colors.amber] as const, [colors]);

  // 三环透明度（浅主题压低保持可读）
  const ringOpacity = dark ? 0.5 : 0.28;
  const scanOpacity = dark ? 0.06 : 0.04;
  const godrayOpacity = dark ? 0.32 : 0.18;

  const ringRefs = useRef<Array<Group | null>>([null, null, null]);
  const ringMaterials = useRef<Array<MeshBasicMaterial | null>>([null, null, null]);
  const scanRef = useRef<Mesh | null>(null);
  const scanMaterial = useRef<MeshBasicMaterial | null>(null);
  const godrayMaterials = useRef<Array<MeshBasicMaterial | null>>([null, null, null, null]);

  useFrame(({ clock }) => {
    const reveal = useExperienceStore.getState().revealProgress;
    const time = motionEnabled ? clock.elapsedTime : 0;

    // 全息数据环：绕 Y 旋转 + 轻微上下浮动；opacity 随 revealProgress 淡入
    for (let index = 0; index < 3; index += 1) {
      const ring = ringRefs.current[index];
      if (!ring) continue;
      ring.rotation.y = time * RING_SPEEDS[index] + RING_PHASES[index];
      ring.position.y =
        RING_HEIGHTS[index] + Math.sin(time * RING_FLOAT_SPEED + RING_PHASES[index]) * RING_FLOAT_AMP;
      const material = ringMaterials.current[index];
      if (material) material.opacity = ringOpacity * reveal;
    }

    // 竖直扫描墙：position.z 在 [-WORLD_SIZE/2, +WORLD_SIZE/2] 间正弦往返
    const scan = scanRef.current;
    if (scan) {
      const phase = (time / SCAN_PERIOD) * Math.PI * 2;
      scan.position.z = Math.sin(phase) * (WORLD_SIZE / 2);
      const material = scanMaterial.current;
      if (material) material.opacity = scanOpacity * reveal;
    }

    // 神光柱：呼吸式 opacity 脉动（四角相位错开）
    for (let index = 0; index < 4; index += 1) {
      const material = godrayMaterials.current[index];
      if (!material) continue;
      const pulse = 0.65 + 0.35 * Math.sin(time * GODRAY_PULSE_SPEED + index * 1.7);
      material.opacity = godrayOpacity * pulse * reveal;
    }
  });

  return (
    <group>
      {/* 核心上方三环 */}
      {[0, 1, 2].map((index) => (
        <group
          key={index}
          ref={(group) => {
            ringRefs.current[index] = group;
          }}
          position={[corePosition[0], RING_HEIGHTS[index], corePosition[1]]}
        >
          <mesh rotation-x={Math.PI / 2}>
            <torusGeometry args={[RING_RADII[index], RING_TUBE, 8, 96]} />
            <meshBasicMaterial
              ref={(material) => {
                ringMaterials.current[index] = material;
              }}
              color={ringColors[index]}
              transparent
              opacity={0}
              blending={AdditiveBlending}
              depthWrite={false}
            />
          </mesh>
        </group>
      ))}

      {/* 竖直扫描墙：法线沿 Z 的竖直平面 */}
      <mesh ref={scanRef} position={[0, GODRAY_HEIGHT * 0.18, 0]}>
        <planeGeometry args={[WORLD_SIZE, GODRAY_HEIGHT * 0.36]} />
        <meshBasicMaterial
          ref={(material) => {
            scanMaterial.current = material;
          }}
          color={colors.cyan}
          transparent
          opacity={0}
          blending={AdditiveBlending}
          depthWrite={false}
          side={DoubleSide}
        />
      </mesh>

      {/* 世界边缘四根神光柱 */}
      {[
        [-GODRAY_OFFSET, -GODRAY_OFFSET],
        [GODRAY_OFFSET, -GODRAY_OFFSET],
        [-GODRAY_OFFSET, GODRAY_OFFSET],
        [GODRAY_OFFSET, GODRAY_OFFSET],
      ].map(([x, z], index) => (
        <mesh key={index} position={[x, GODRAY_HEIGHT / 2, z]}>
          <cylinderGeometry args={[GODRAY_RADIUS, GODRAY_RADIUS * 1.6, GODRAY_HEIGHT, 12, 1, true]} />
          <meshBasicMaterial
            ref={(material) => {
              godrayMaterials.current[index] = material;
            }}
            color={index % 2 === 0 ? colors.violet : colors.cyan}
            transparent
            opacity={0}
            blending={AdditiveBlending}
            depthWrite={false}
            side={DoubleSide}
          />
        </mesh>
      ))}
    </group>
  );
}
