import * as THREE from 'three';
import { RoundedBox } from '@react-three/drei';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * StateStorageArray - 状态管理存储阵列模块
 * 业务能力：state状态管理，保存上下文、状态快照
 */

// 单个硬盘仓位组件，含状态指示灯
function DriveBay({
  position,
  active = true,
  color,
  dark,
}: {
  position: [number, number, number];
  active?: boolean;
  color: string;
  dark: boolean;
}) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Color-tinted variants for light mode derived from node palette color
  const shellBase = new THREE.Color(color);
  const bayColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const panelColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const bayColor = dark ? darkShell('#1a1a2e', color) : bayColorLight;
  const panelColor = dark ? darkShell('#2a2a44', color) : panelColorLight;

  return (
    <group position={position}>
      {/* 硬盘仓位本体 */}
      <RoundedBox args={[0.28, 0.06, 0.35]} radius={0.01} smoothness={4}>
        <meshStandardMaterial
          color={bayColor}
          roughness={0.7}
          metalness={0.8}
        />
      </RoundedBox>

      {/* 仓位前面板装饰条 */}
      <RoundedBox args={[0.24, 0.015, 0.01]} radius={0.005} smoothness={4} position={[0, 0, 0.18]}>
        <meshStandardMaterial
          color={panelColor}
          roughness={0.5}
          metalness={0.9}
        />
      </RoundedBox>

      {/* 状态指示灯 */}
      <mesh position={[0.1, 0.035, 0.16]}>
        <sphereGeometry args={[0.018, 16, 16]} />
        <meshStandardMaterial
          color={active ? color : '#4a4a6a'}
          emissive={active ? color : '#000000'}
          emissiveIntensity={active ? 2.5 * emissiveScale : 0}
          roughness={0.2}
          metalness={0.3}
          toneMapped={false}
        />
      </mesh>

      {/* 指示灯辉光外壳 */}
      <mesh position={[0.1, 0.035, 0.16]}>
        <sphereGeometry args={[0.025, 16, 16]} />
        <meshStandardMaterial
          color={color}
          transparent
          opacity={active ? 0.25 : 0.05}
          roughness={0.8}
          metalness={0.1}
        />
      </mesh>
    </group>
  );
}

export default function StateStorageArray({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Color-tinted variants for light mode derived from node palette color
  const shellBase = new THREE.Color(color);
  const shellColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const ventColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const baseColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();
  const portColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const shellColor = dark ? darkShell('#12121e', color) : shellColorLight;
  const ventColor = dark ? darkShell('#1e1e30', color) : ventColorLight;
  const baseColor = dark ? darkShell('#0e0e1a', color, 0.25, 0.12) : baseColorLight;
  const portColor = dark ? darkShell('#2a2a44', color) : portColorLight;

  const bayPositions: [number, number, number][] = [
    [0, 0.27, 0],
    [0, 0.09, 0],
    [0, -0.09, 0],
    [0, -0.27, 0],
  ];

  const bayActiveStates = [true, true, false, true];

  return (
    <group>
        {/* ===== 主外壳 ===== */}
        <RoundedBox args={[0.55, 0.75, 0.5]} radius={0.06} smoothness={4}>
          <meshStandardMaterial
            color={shellColor}
            roughness={0.75}
            metalness={0.85}
          />
        </RoundedBox>

        {/* 外壳顶部散热格栅 */}
        {[...Array(5)].map((_, i) => (
          <RoundedBox
            key={`vent-${i}`}
            args={[0.35, 0.008, 0.03]}
            radius={0.003}
            smoothness={4}
            position={[0, 0.38, -0.12 + i * 0.06]}
          >
            <meshStandardMaterial
              color={ventColor}
              roughness={0.6}
              metalness={0.9}
            />
          </RoundedBox>
        ))}

        {/* 外壳底部基座 */}
        <RoundedBox args={[0.58, 0.04, 0.52]} radius={0.02} smoothness={4} position={[0, -0.39, 0]}>
          <meshStandardMaterial
            color={baseColor}
            roughness={0.8}
            metalness={0.9}
          />
        </RoundedBox>

        {/* 左侧面板 - 半透明玻璃观察窗 */}
        <RoundedBox args={[0.01, 0.5, 0.35]} radius={0.005} smoothness={4} position={[-0.28, 0, 0]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.12}
            roughness={0.9}
            metalness={0.2}
          />
        </RoundedBox>

        {/* 右侧面板 */}
        <RoundedBox args={[0.01, 0.5, 0.35]} radius={0.005} smoothness={4} position={[0.28, 0, 0]}>
          <meshStandardMaterial
            color={color}
            transparent
            opacity={0.12}
            roughness={0.9}
            metalness={0.2}
          />
        </RoundedBox>

        {/* ===== 硬盘仓位组 ===== */}
        <group position={[0, 0, 0.02]}>
          {bayPositions.map((pos, index) => (
            <DriveBay
              key={`bay-${index}`}
              position={pos}
              active={bayActiveStates[index]}
              color={color}
              dark={dark}
            />
          ))}
        </group>

        {/* 顶部状态标识灯带 */}
        <RoundedBox args={[0.3, 0.012, 0.012]} radius={0.005} smoothness={4} position={[0, 0.36, 0.24]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.8 * emissiveScale}
            roughness={0.3}
            metalness={0.4}
            toneMapped={false}
          />
        </RoundedBox>

        {/* 底部接口区域装饰 */}
        {[...Array(3)].map((_, i) => (
          <RoundedBox
            key={`port-${i}`}
            args={[0.06, 0.025, 0.015]}
            radius={0.005}
            smoothness={4}
            position={[-0.1 + i * 0.1, -0.34, 0.25]}
          >
            <meshStandardMaterial
              color={portColor}
              roughness={0.5}
              metalness={0.9}
            />
          </RoundedBox>
        ))}
    </group>
  );
}
