// 玩家化身：发光光点（内芯+外晕）+ 速度感应拖尾 ribbon + 移动方向前倾。
// 每帧读 playerWorld，零 React 状态更新。拖尾用固定长度环形缓冲，零每帧分配。

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { BufferAttribute, BufferGeometry, Color, MathUtils } from "three";
import type { Group } from "three";
import { playerWorld } from "../world";
import { palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { useExperienceStore } from "../store";
import { soundEngine } from "../systems/soundEngine";

const TRAIL_LENGTH = 22;
const tmpColor = new Color();

export function PlayerAvatar({ theme, motionEnabled }: { theme: ThemeName; motionEnabled: boolean }) {
  const bodyRef = useRef<Group>(null);
  const glowRef = useRef<Group>(null);
  const trailRef = useRef<BufferGeometry>(null);
  const trailPoints = useRef<Float32Array>(new Float32Array(TRAIL_LENGTH * 3));
  const trailHead = useRef(0);
  const initialized = useRef(false);
  const wasGrounded = useRef(true);
  const wasSprinting = useRef(false);
  const colors = palette[theme];

  const trailGeometry = useMemo(() => {
    const geometry = new BufferGeometry();
    geometry.setAttribute("position", new BufferAttribute(new Float32Array((TRAIL_LENGTH - 1) * 2 * 3), 3));
    const colorsArray = new Float32Array((TRAIL_LENGTH - 1) * 2 * 3);
    geometry.setAttribute("color", new BufferAttribute(colorsArray, 3));
    return geometry;
  }, []);

  useFrame((state, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    const player = playerWorld;
    const speedNorm = Math.min(1, player.speed / 12);
    const body = bodyRef.current;
    if (!body) return;

    // 落地音
    if (player.grounded && !wasGrounded.current && soundEngine.enabled) soundEngine.play("land");
    wasGrounded.current = player.grounded;

    // 冲刺起步音：速度首破阈值（WALK 7 与 RUN 12.25 之间）时触发，回落后复位
    const { started } = useExperienceStore.getState();
    if (started && player.speed > 8 && !wasSprinting.current) {
      wasSprinting.current = true;
      if (soundEngine.enabled) soundEngine.play("sprintStart");
    } else if (player.speed < 6) {
      wasSprinting.current = false;
    }

    // 主体跟随 + 前倾（速度感应）
    body.position.set(player.x, player.y + 0.72, player.z);
    const leanX = MathUtils.clamp(-player.vz * 0.028, -0.32, 0.32);
    const leanZ = MathUtils.clamp(player.vx * 0.028, -0.32, 0.32);
    body.rotation.x += (leanX - body.rotation.x) * (1 - Math.exp(-delta * 7));
    body.rotation.z += (leanZ - body.rotation.z) * (1 - Math.exp(-delta * 7));
    body.rotation.y = player.heading;

    // 脉动光环
    const glow = glowRef.current;
    if (glow) {
      const pulse = motionEnabled ? 1 + Math.sin(state.clock.elapsedTime * 4) * 0.12 : 1;
      glow.scale.setScalar((1 + speedNorm * 0.5) * pulse);
    }

    // 拖尾：环形缓冲写入当前点，再重建线段位置数组
    if (!initialized.current) {
      for (let index = 0; index < TRAIL_LENGTH; index += 1) {
        trailPoints.current[index * 3] = player.x;
        trailPoints.current[index * 3 + 1] = player.y + 0.72;
        trailPoints.current[index * 3 + 2] = player.z;
      }
      initialized.current = true;
    }
    trailHead.current = (trailHead.current + 1) % TRAIL_LENGTH;
    trailPoints.current[trailHead.current * 3] = player.x;
    trailPoints.current[trailHead.current * 3 + 1] = player.y + 0.72;
    trailPoints.current[trailHead.current * 3 + 2] = player.z;

    const geometry = trailRef.current;
    if (geometry) {
      const positions = geometry.getAttribute("position") as BufferAttribute;
      const colorAttr = geometry.getAttribute("color") as BufferAttribute;
      tmpColor.set(colors.cyan);
      let vertex = 0;
      const segments = Math.floor(MathUtils.lerp(5, TRAIL_LENGTH - 1, speedNorm));
      for (let segment = 0; segment < TRAIL_LENGTH - 1; segment += 1) {
        const a = (trailHead.current - segment + TRAIL_LENGTH * 2) % TRAIL_LENGTH;
        const b = (trailHead.current - segment - 1 + TRAIL_LENGTH * 2) % TRAIL_LENGTH;
        const visible = segment < segments;
        positions.setXYZ(vertex, visible ? trailPoints.current[a * 3] : player.x, visible ? trailPoints.current[a * 3 + 1] : -100, visible ? trailPoints.current[a * 3 + 2] : player.z);
        const fadeA = visible ? 1 - segment / TRAIL_LENGTH : 0;
        colorAttr.setXYZ(vertex, tmpColor.r * fadeA, tmpColor.g * fadeA, tmpColor.b * fadeA);
        vertex += 1;
        positions.setXYZ(vertex, visible ? trailPoints.current[b * 3] : player.x, visible ? trailPoints.current[b * 3 + 1] : -100, visible ? trailPoints.current[b * 3 + 2] : player.z);
        const fadeB = visible ? 1 - (segment + 1) / TRAIL_LENGTH : 0;
        colorAttr.setXYZ(vertex, tmpColor.r * fadeB, tmpColor.g * fadeB, tmpColor.b * fadeB);
        vertex += 1;
      }
      positions.needsUpdate = true;
      colorAttr.needsUpdate = true;
    }
  });

  return (
    <group>
      <group ref={bodyRef}>
        {/* 内芯 */}
        <mesh>
          <sphereGeometry args={[0.3, 24, 24]} />
          <meshStandardMaterial color={colors.cyan} emissive={colors.cyan} emissiveIntensity={2.4} roughness={0.2} metalness={0.1} />
        </mesh>
        {/* 外晕 */}
        <group ref={glowRef}>
          <mesh>
            <sphereGeometry args={[0.52, 24, 24]} />
            <meshBasicMaterial color={colors.cyan} transparent opacity={0.22} />
          </mesh>
          <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.45, 0]}>
            <ringGeometry args={[0.42, 0.5, 40]} />
            <meshBasicMaterial color={colors.cyan} transparent opacity={0.5} side={2} />
          </mesh>
        </group>
        {/* 顶部小尖标，指示朝向 */}
        <mesh position={[0, 0.42, 0.2]}>
          <coneGeometry args={[0.09, 0.26, 12]} />
          <meshBasicMaterial color={theme === "light" ? "#162235" : "#eef2ff"} />
        </mesh>
      </group>
      {/* 拖尾 ribbon */}
      <lineSegments ref={(value) => { trailRef.current = (value as unknown as { geometry: BufferGeometry } | null)?.geometry ?? null; }} frustumCulled={false}>
        <primitive object={trailGeometry} attach="geometry" />
        <lineBasicMaterial vertexColors transparent opacity={0.85} blending={2} depthWrite={false} />
      </lineSegments>
      {/* 地面投影（假阴影） */}
      <FakeShadow theme={theme} />
    </group>
  );
}

function FakeShadow({ theme }: { theme: ThemeName }) {
  const ref = useRef<Group>(null);
  useFrame(() => {
    const player = playerWorld;
    if (!ref.current) return;
    ref.current.position.set(player.x, 0.035, player.z);
    const squash = MathUtils.clamp(1 - player.y * 0.16, 0.35, 1);
    ref.current.scale.setScalar(squash);
  });
  return (
    <group ref={ref}>
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry args={[0.55, 28]} />
        <meshBasicMaterial color={theme === "light" ? "#93a7bb" : "#000000"} transparent opacity={theme === "light" ? 0.3 : 0.5} depthWrite={false} />
      </mesh>
    </group>
  );
}
