import { useMemo } from 'react';
import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * DeliveryModule - 交付投递舱模块
 * 业务语义：聚合结果向外输出投递
 */
export function DeliveryModule({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Color-tinted shell/body colors derived from node palette color
  const shellBase = useMemo(() => new THREE.Color(color), [color]);
  const bodyColorLight = useMemo(
    () => '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.6).getHexString(),
    [shellBase]
  );
  // 暗色外壳注入节点色相，避免与深色背景同化
  const bodyColor = dark ? darkShell('#2a3444', color) : bodyColorLight;
  const glassColorVal = dark ? darkShell('#1a2535', color, 0.25, 0.12) : '#d0e8f8';

  // 输出光束材质
  const beamMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: color,
    emissive: color,
    emissiveIntensity: 2.5 * emissiveScale,
    transparent: true,
    opacity: 0.85,
    roughness: 0.1,
    metalness: 0.1,
  }), [color, emissiveScale]);

  // 主体金属材质
  const bodyMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: bodyColor,
    roughness: 0.65,
    metalness: 0.7,
  }), [bodyColor]);

  // 半透明磨砂玻璃材质
  const glassMaterial = useMemo(() => new THREE.MeshStandardMaterial({
    color: glassColorVal,
    transparent: true,
    opacity: 0.35,
    roughness: 0.4,
    metalness: 0.2,
  }), [glassColorVal]);

  return (
      <group>
        {/* === 输入端 === */}
        <mesh position={[0, 0.35, 0]} material={bodyMaterial}>
          <cylinderGeometry args={[0.55, 0.45, 0.4, 32]} />
        </mesh>

        <mesh position={[0, 0.35, 0]} material={glassMaterial}>
          <cylinderGeometry args={[0.48, 0.38, 0.38, 32]} />
        </mesh>

        <mesh position={[0, 0.56, 0]} rotation={[Math.PI / 2, 0, 0]} material={bodyMaterial}>
          <torusGeometry args={[0.52, 0.03, 16, 32]} />
        </mesh>

        {/* === 中段锥体 === */}
        <mesh position={[0, -0.05, 0]} material={bodyMaterial}>
          <cylinderGeometry args={[0.45, 0.22, 0.5, 32]} />
        </mesh>

        <mesh position={[0, -0.05, 0]} material={glassMaterial}>
          <cylinderGeometry args={[0.38, 0.18, 0.48, 32]} />
        </mesh>

        <mesh position={[0, 0.12, 0]} rotation={[Math.PI / 2, 0, 0]} material={bodyMaterial}>
          <torusGeometry args={[0.34, 0.02, 12, 32]} />
        </mesh>

        <mesh position={[0, -0.22, 0]} rotation={[Math.PI / 2, 0, 0]} material={bodyMaterial}>
          <torusGeometry args={[0.24, 0.02, 12, 32]} />
        </mesh>

        {/* === 输出端 === */}
        <mesh position={[0, -0.48, 0]} material={bodyMaterial}>
          <cylinderGeometry args={[0.22, 0.18, 0.35, 32]} />
        </mesh>

        <mesh position={[0, -0.48, 0]} material={glassMaterial}>
          <cylinderGeometry args={[0.17, 0.14, 0.33, 32]} />
        </mesh>

        <mesh position={[0, -0.66, 0]} rotation={[Math.PI / 2, 0, 0]} material={bodyMaterial}>
          <torusGeometry args={[0.19, 0.025, 12, 32]} />
        </mesh>

        {/* === 输出数据流光束 === */}
        <mesh position={[0, -0.78, 0]} material={beamMaterial}>
          <cylinderGeometry args={[0.12, 0.02, 0.25, 16]} />
        </mesh>

        {/* 光束外晕 */}
        <mesh position={[0, -0.82, 0]}>
          <cylinderGeometry args={[0.16, 0.04, 0.18, 16]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.5 * emissiveScale}
            transparent
            opacity={0.3}
            roughness={0.1}
          />
        </mesh>

        {/* 光束核心亮点 */}
        <mesh position={[0, -0.85, 0]}>
          <sphereGeometry args={[0.04, 16, 16]} />
          <meshStandardMaterial
            color="#ffffff"
            emissive={color}
            emissiveIntensity={4 * emissiveScale}
            transparent
            opacity={0.9}
          />
        </mesh>

        {/* === 侧面安装支架 === */}
        <RoundedBox args={[0.08, 0.25, 0.06]} radius={0.015} position={[-0.52, 0.1, 0]} material={bodyMaterial} />
        <RoundedBox args={[0.08, 0.25, 0.06]} radius={0.015} position={[0.52, 0.1, 0]} material={bodyMaterial} />

        {/* 状态指示条 */}
        <RoundedBox args={[0.04, 0.15, 0.02]} radius={0.008} position={[0.42, 0.1, 0.18]}>
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={1.8 * emissiveScale}
            roughness={0.2}
          />
        </RoundedBox>
      </group>
  );
}
