// 冲刺速度粒子尾迹：玩家 speed 超过阈值（接近跑步/冲刺）时，从身后以反方向 + 随机散射洒出渐隐粒子。
// 固定容量环形缓冲 + Points 单 draw call + AdditiveBlending + vertexColors（亮度写入 color attribute），
// useFrame 内零分配，死亡粒子藏 y=-100；motionEnabled=false 时停止发射仅让存量粒子自然衰减。
// 浅色主题整体压低亮度，避免 additive 在白底上反白刺眼。

import { useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import { AdditiveBlending, BufferAttribute, BufferGeometry, Color } from "three";
import { palette } from "../../experience/experienceData";
import type { ThemeName } from "../../experience/experienceData";
import { playerWorld } from "../world";
import { useExperienceStore } from "../store";

const MAX_PARTICLES = 120;
const LIFETIME = 0.5;
// 触发阈值：约等于"接近跑步/冲刺"的速度，低于此值完全不发射
const SPEED_THRESHOLD = 6;
// 满速参考：以该速度为 1.0 计算发射速率/方向强度
const SPEED_FULL = 10;
// 每秒最多发射的粒子数（满速时达到上限）
const EMIT_RATE_MAX = 90;

type SpeedTrailProps = {
  theme: ThemeName;
  motionEnabled: boolean;
};

export function SpeedTrail({ theme, motionEnabled }: SpeedTrailProps) {
  const colors = palette[theme];
  const dark = theme !== "light";

  const positions = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const velocities = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const ages = useMemo(() => new Float32Array(MAX_PARTICLES).fill(LIFETIME + 1), []);
  // 粒子基础颜色（出生瞬间的满亮度 RGB），每帧用 fade 缩放后写入 geometry color attribute
  const particleColors = useMemo(() => new Float32Array(MAX_PARTICLES * 3), []);
  const cursor = useRef(0);
  // 发射节流：累积"欠发"的时间，避免低帧率下爆发 / 高帧率下稀疏
  const emitAccumulator = useRef(0);
  const baseColor = useMemo(() => new Color(), []);

  // 主题或基础色变化时刷新缓存的 Color 实例
  baseColor.set(colors.cyan);
  // 浅色主题整体降一档亮度，避免 additive 在白底上对比过强
  const brightnessScale = dark ? 1 : 0.55;

  const geometry = useMemo(() => {
    const buffer = new BufferGeometry();
    buffer.setAttribute("position", new BufferAttribute(positions, 3));
    buffer.setAttribute("color", new BufferAttribute(particleColors, 3));
    return buffer;
  }, [positions, particleColors]);

  useFrame((_, rawDelta) => {
    const delta = Math.min(rawDelta, 0.05);
    const started = useExperienceStore.getState().started;

    // —— 发射阶段 ——
    // 仅在已开始且开启动效时发射新粒子；motionEnabled=false 时只让存量粒子淡出。
    if (started && motionEnabled) {
      const speed = playerWorld.speed;
      if (speed > SPEED_THRESHOLD) {
        const speedNorm = Math.min(1, (speed - SPEED_THRESHOLD) / (SPEED_FULL - SPEED_THRESHOLD));
        emitAccumulator.current += delta * EMIT_RATE_MAX * speedNorm;
        // 反方向单位向量（XZ 平面），玩家速度反方向 = 尾迹抛出方向
        // 用 heading 而不是 vx/vz 可以避免零速抖动
        const backX = -Math.sin(playerWorld.heading);
        const backZ = -Math.cos(playerWorld.heading);
        while (emitAccumulator.current >= 1) {
          emitAccumulator.current -= 1;
          const slot = cursor.current;
          cursor.current = (cursor.current + 1) % MAX_PARTICLES;
          const base = slot * 3;
          // 出生位置：玩家胸口附近，加少量径向抖动让尾迹不是一条死直线
          positions[base] = playerWorld.x + (Math.random() - 0.5) * 0.25;
          positions[base + 1] = playerWorld.y + 0.5 + (Math.random() - 0.5) * 0.2;
          positions[base + 2] = playerWorld.z + (Math.random() - 0.5) * 0.25;
          // 初速：反方向 × 速度比例 + 随机散射 + 轻微上飘
          const spread = 0.9;
          velocities[base] = backX * (1.4 + speedNorm * 1.6) + (Math.random() - 0.5) * spread;
          velocities[base + 1] = 0.6 + Math.random() * 0.9;
          velocities[base + 2] = backZ * (1.4 + speedNorm * 1.6) + (Math.random() - 0.5) * spread;
          ages[slot] = 0;
          particleColors[base] = baseColor.r * brightnessScale;
          particleColors[base + 1] = baseColor.g * brightnessScale;
          particleColors[base + 2] = baseColor.b * brightnessScale;
        }
      } else {
        // 速度掉回阈值以下时清空累积，避免重新加速瞬间大量补发
        emitAccumulator.current = 0;
      }
    } else {
      emitAccumulator.current = 0;
    }

    // —— 积分 + 渐隐 ——
    let dirty = false;
    const positionAttr = geometry.getAttribute("position");
    const colorAttr = geometry.getAttribute("color");
    for (let slot = 0; slot < MAX_PARTICLES; slot += 1) {
      if (ages[slot] > LIFETIME) {
        if (positions[slot * 3 + 1] > -50) {
          positions[slot * 3 + 1] = -100; // 藏到地下，GPU 端不再可见
          dirty = true;
        }
        continue;
      }
      ages[slot] += delta;
      const base = slot * 3;
      // 轻微上飘 + 扩散：y 方向加一个恒定小升力，XZ 方向随时间略微放大
      velocities[base + 1] += 0.6 * delta;
      positions[base] += velocities[base] * delta;
      positions[base + 1] += velocities[base + 1] * delta;
      positions[base + 2] += velocities[base + 2] * delta;
      const fade = Math.max(0, 1 - ages[slot] / LIFETIME);
      const brightness = fade * fade;
      colorAttr.setXYZ(
        slot,
        particleColors[base] * brightness,
        particleColors[base + 1] * brightness,
        particleColors[base + 2] * brightness,
      );
      dirty = true;
    }
    if (dirty) {
      positionAttr.needsUpdate = true;
      colorAttr.needsUpdate = true;
    }
  });

  return (
    <points geometry={geometry} frustumCulled={false}>
      <pointsMaterial
        size={0.14}
        vertexColors
        transparent
        blending={AdditiveBlending}
        depthWrite={false}
        sizeAttenuation
      />
    </points>
  );
}
