// 3D 体验馆音频引擎：分层合成音效系统（Web Audio，零外部资源）。
//
// 设计要点：
// - 单例 class + 惰性 ensure()：绝不在模块加载阶段 new AudioContext（浏览器要求用户手势）；
//   所有节点创建都走 ensure()，且 context suspended 时一律 resume。
// - 分层合成基元：
//     tone()  —— 振荡器 + 指数包络（8ms 起音防爆音），可选 glide / 目标频率 / 声像；
//     noise() —— 模块级缓存 1s 白噪声 AudioBuffer，经 BiquadFilter 塑形做 whoosh / 尘埃感；
//     每种音效 = 基频层 + 泛音层 + 噪声塑形层 的组合，避免"单个 tone 干响"。
// - 总线：master gain 0.075 接 destination；effect 音量分级克制——
//     near/hover 轻（0.1~0.2）、burst/milestone 亮（0.3~0.5）、ambience 垫底（峰值 0.18 进独立 pad 总线）。
// - 引擎底噪：sawtooth（基频）+ sub sine（低八度厚重感）+ 锯齿泛音层（volume*0.4）三路
//   经同一 lowpass，滤波 220→860Hz、音量随 speedNorm 开合；上缓 0.3s / 下缓 0.15s。
// - ambience：两个失谐 ±3 cents 锯齿 + 慢 LFO(0.07Hz) 调幅 + lowpass 880Hz，
//   startAmbience(progress) 幂等可重复调用，音量随 revealProgress 淡入。
// - 生命周期：所有一次性节点靠 oscillator.stop() + onended disconnect 自动回收；
//   常驻节点（engine / ambience）在 dispose() 中显式停止、断连并 close context。
//
// 性能要点：除 AudioBuffer 一次性缓存外无模块级大对象；每个 play 调用只创建必要节点，
// 播放结束即回收；updateEngine 每帧只做 setTargetAtTime（参数自动化，无节点创建）。

export type SoundEffect =
  | "start" | "click" | "hover" | "step" | "burst" | "close" | "jump" | "land"
  | "near" | "warp" | "milestone" | "complete" | "ambience" | "sprintStart";

type EngineNodes = {
  oscillator: OscillatorNode;
  sub: OscillatorNode;
  subGain: GainNode;
  gain: GainNode;
  filter: BiquadFilterNode;
};

type AmbienceNodes = {
  oscA: OscillatorNode;
  oscB: OscillatorNode;
  lfo: OscillatorNode;
  lfoGain: GainNode;
  gain: GainNode;
  filter: BiquadFilterNode;
};

type ToneOptions = {
  type?: OscillatorType;
  /** 线性 glide 的 ΔHz（正上滑 / 负下滑） */
  glide?: number;
  /** 到达目标频率（exponentialRamp，与 glide 二选一；音色更"空间"） */
  toFrequency?: number;
  /** 起音时长（秒），默认 0.008 防爆音 */
  attack?: number;
  /** 声像 -1..1（StereoPanner，缺省中置） */
  pan?: number;
  /** 播放结束后额外停留秒数（默认 0.02） */
  tail?: number;
};

type NoiseOptions = {
  /** 滤波类型：whoosh 用 bandpass，尘埃/垫底用 lowpass/highpass */
  filterType?: BiquadFilterType;
  /** 滤波起始频率 */
  from?: number;
  /** 滤波扫频目标频率（指数扫） */
  to?: number;
  /** 滤波 Q */
  q?: number;
  /** 声像 -1..1 */
  pan?: number;
  /** 起音时长（秒），默认 0.006 */
  attack?: number;
  /** 噪声源播放速率（默认 1；<1 更低沉） */
  playbackRate?: number;
};

class ExperienceSoundEngine {
  private context: AudioContext | null = null;
  private master: GainNode | null = null;
  private noiseBuffer: AudioBuffer | null = null;
  private engine: EngineNodes | null = null;
  private engineTargetRate = 0;
  private ambience: AmbienceNodes | null = null;
  enabled = true;

  /** 惰性初始化：只在用户手势触发的 play/startEngine 路径上创建 AudioContext */
  private ensure() {
    if (this.context) return true;
    if (typeof window === "undefined" || !window.AudioContext) return false;
    this.context = new window.AudioContext();
    this.master = this.context.createGain();
    this.master.gain.value = 0.075;
    this.master.connect(this.context.destination);
    return true;
  }

  /** 模块级缓存一份 1s 白噪声，所有噪声层共享 */
  private ensureNoiseBuffer() {
    if (!this.context) return null;
    if (this.noiseBuffer) return this.noiseBuffer;
    const length = Math.floor(this.context.sampleRate * 1);
    const buffer = this.context.createBuffer(1, length, this.context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let index = 0; index < length; index += 1) {
      data[index] = Math.random() * 2 - 1;
    }
    this.noiseBuffer = buffer;
    return buffer;
  }

  /** 振荡器分层基元：指数包络 + 可选 glide / 频率迁移 / 声像，结束自动断连 */
  private tone(frequency: number, duration: number, offset: number, volume: number, options: ToneOptions = {}) {
    if (!this.context || !this.master) return;
    if (this.context.state === "suspended") void this.context.resume();
    const { type = "sine", glide = 0, toFrequency = 0, attack = 0.008, pan = 0, tail = 0.02 } = options;
    const now = this.context.currentTime;
    const startAt = now + offset;
    const endAt = startAt + duration;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(Math.max(1, frequency), startAt);
    if (toFrequency > 0) {
      oscillator.frequency.exponentialRampToValueAtTime(Math.max(1, toFrequency), endAt);
    } else if (glide !== 0) {
      oscillator.frequency.linearRampToValueAtTime(Math.max(1, frequency + glide), endAt);
    }
    gain.gain.setValueAtTime(0.0001, startAt);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), startAt + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, endAt);
    oscillator.connect(gain);
    let output: AudioNode = gain;
    if (pan !== 0 && typeof this.context.createStereoPanner === "function") {
      const panner = this.context.createStereoPanner();
      panner.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), startAt);
      output.connect(panner);
      output = panner;
    }
    output.connect(this.master);
    oscillator.onended = () => {
      try { oscillator.disconnect(); } catch { /* 已断连 */ }
      try { gain.disconnect(); } catch { /* 已断连 */ }
      if (output !== gain) { try { output.disconnect(); } catch { /* 已断连 */ } }
    };
    oscillator.start(startAt);
    oscillator.stop(endAt + tail);
  }

  /** 噪声塑形基元：缓存白噪声 → BiquadFilter（可扫频）→ 指数包络，做 whoosh / 尘埃感 */
  private noise(duration: number, offset: number, volume: number, options: NoiseOptions = {}) {
    if (!this.context || !this.master) return;
    const buffer = this.ensureNoiseBuffer();
    if (!buffer) return;
    if (this.context.state === "suspended") void this.context.resume();
    const { filterType = "bandpass", from = 800, to = 0, q = 1, pan = 0, attack = 0.006, playbackRate = 1 } = options;
    const now = this.context.currentTime;
    const startAt = now + offset;
    const endAt = startAt + duration;
    const source = this.context.createBufferSource();
    source.buffer = buffer;
    source.loop = true;
    source.playbackRate.setValueAtTime(playbackRate, startAt);
    const filter = this.context.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(Math.max(20, from), startAt);
    filter.Q.setValueAtTime(q, startAt);
    if (to > 0) {
      filter.frequency.exponentialRampToValueAtTime(Math.max(20, to), endAt);
    }
    const gain = this.context.createGain();
    gain.gain.setValueAtTime(0.0001, startAt);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), startAt + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, endAt);
    source.connect(filter);
    filter.connect(gain);
    let output: AudioNode = gain;
    if (pan !== 0 && typeof this.context.createStereoPanner === "function") {
      const panner = this.context.createStereoPanner();
      panner.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), startAt);
      output.connect(panner);
      output = panner;
    }
    output.connect(this.master);
    source.onended = () => {
      try { source.disconnect(); } catch { /* 已断连 */ }
      try { filter.disconnect(); } catch { /* 已断连 */ }
      try { gain.disconnect(); } catch { /* 已断连 */ }
      if (output !== gain) { try { output.disconnect(); } catch { /* 已断连 */ } }
    };
    source.start(startAt);
    source.stop(endAt + 0.02);
  }

  play(effect: SoundEffect) {
    if (!this.enabled) return;
    if (!this.ensure()) return;
    switch (effect) {
      case "start": {
        // 启动：基频 + 泛音 + 高频空气层 + 轻噪声扫频（上扬建立感）
        this.tone(196, 0.22, 0, 0.4, { type: "sine", glide: 38 });
        this.tone(98, 0.26, 0, 0.22, { type: "sine" });
        this.tone(294, 0.24, 0.07, 0.3, { type: "triangle", glide: 54 });
        this.tone(588, 0.38, 0.15, 0.2, { type: "sine", glide: 80 });
        this.tone(1176, 0.3, 0.2, 0.08, { type: "sine", glide: 60 });
        this.noise(0.35, 0, 0.05, { filterType: "bandpass", from: 900, to: 3600, q: 0.9 });
        break;
      }
      case "click": {
        // 点击：短促方波基频 + 高频泛音回落 + 尘噪点缀
        this.tone(240, 0.11, 0, 0.3, { type: "square", glide: 120 });
        this.tone(480, 0.09, 0.01, 0.14, { type: "triangle", glide: -60 });
        this.tone(720, 0.16, 0.025, 0.15, { type: "sine", glide: -90 });
        this.noise(0.06, 0, 0.05, { filterType: "highpass", from: 3800, q: 0.7 });
        break;
      }
      case "hover": {
        // 悬停：极轻，基频 + 微泛音
        this.tone(620, 0.08, 0, 0.15, { type: "sine", glide: 45 });
        this.tone(930, 0.07, 0.015, 0.05, { type: "sine", glide: 30 });
        break;
      }
      case "step": {
        // 脚步：低三角 + 极低噪声"踏地"感
        this.tone(110, 0.055, 0, 0.12, { type: "triangle", glide: -18 });
        this.noise(0.045, 0, 0.05, { filterType: "lowpass", from: 420, q: 0.6, playbackRate: 0.7 });
        break;
      }
      case "burst": {
        // 选中爆发：基频锯齿上冲 + 泛音堆叠 + 宽噪声 whoosh
        this.tone(340, 0.18, 0, 0.32, { type: "sawtooth", glide: 260 });
        this.tone(170, 0.2, 0, 0.18, { type: "triangle", glide: 130 });
        this.tone(680, 0.24, 0.05, 0.22, { type: "triangle", glide: 200 });
        this.tone(1020, 0.3, 0.1, 0.15, { type: "sine", glide: 160 });
        this.noise(0.3, 0, 0.08, { filterType: "bandpass", from: 600, to: 4200, q: 1.1 });
        break;
      }
      case "close": {
        // 关闭：基频 + 泛音双下滑 + 低噪声收束
        this.tone(520, 0.1, 0, 0.26, { type: "triangle", glide: -180 });
        this.tone(300, 0.14, 0.05, 0.18, { type: "sine", glide: -120 });
        this.tone(780, 0.1, 0.02, 0.08, { type: "sine", glide: -200 });
        this.noise(0.12, 0, 0.04, { filterType: "lowpass", from: 900, to: 260, q: 0.8 });
        break;
      }
      case "jump": {
        // 跳跃：正弦上扬 + 高泛音跟滑
        this.tone(300, 0.13, 0, 0.22, { type: "sine", glide: 180 });
        this.tone(600, 0.11, 0.03, 0.1, { type: "sine", glide: 160 });
        break;
      }
      case "land": {
        // 落地：低三角 + 亚正弦 + 低噪声"触地"闷响
        this.tone(120, 0.09, 0, 0.28, { type: "triangle", glide: -50 });
        this.tone(60, 0.1, 0, 0.16, { type: "sine", glide: -12 });
        this.noise(0.07, 0, 0.06, { filterType: "lowpass", from: 500, q: 0.7, playbackRate: 0.6 });
        break;
      }
      case "near": {
        // 进入感应圈：柔和上滑双音（纯五度）+ 轻泛音，干净不刺耳
        this.tone(392, 0.16, 0, 0.14, { type: "sine", glide: 30, attack: 0.02 });
        this.tone(588, 0.18, 0.07, 0.12, { type: "sine", glide: 36, attack: 0.02 });
        this.tone(1176, 0.12, 0.11, 0.04, { type: "sine", glide: 20, attack: 0.03 });
        break;
      }
      case "warp": {
        // 相机模式切换：带通噪声大幅扫频 whoosh + 下滑锯齿 + 长尾衰减（空间感）
        this.noise(0.5, 0, 0.14, { filterType: "bandpass", from: 300, to: 3400, q: 1.6, attack: 0.05 });
        this.noise(0.55, 0.02, 0.06, { filterType: "bandpass", from: 2400, to: 500, q: 1.2, attack: 0.03 });
        this.tone(880, 0.5, 0, 0.14, { type: "sawtooth", toFrequency: 180, attack: 0.01 });
        this.tone(1320, 0.44, 0.04, 0.06, { type: "sine", toFrequency: 320, attack: 0.02 });
        break;
      }
      case "milestone": {
        // 探索里程碑：明亮上行琶音三音（大三和弦 1-3-5）+ 顶泛音
        this.tone(523.25, 0.16, 0, 0.26, { type: "triangle", attack: 0.01 });
        this.tone(659.25, 0.18, 0.09, 0.26, { type: "triangle", attack: 0.01 });
        this.tone(783.99, 0.3, 0.18, 0.28, { type: "triangle", attack: 0.01 });
        this.tone(1567.98, 0.26, 0.2, 0.08, { type: "sine", attack: 0.015 });
        break;
      }
      case "complete": {
        // 全探索胜利和弦：长琶音（1-3-5-高八度）+ 低音垫底 + 噪声升腾
        this.tone(523.25, 0.24, 0, 0.24, { type: "triangle", attack: 0.012 });
        this.tone(659.25, 0.26, 0.12, 0.24, { type: "triangle", attack: 0.012 });
        this.tone(783.99, 0.3, 0.24, 0.24, { type: "triangle", attack: 0.012 });
        this.tone(1046.5, 0.55, 0.36, 0.26, { type: "triangle", attack: 0.012 });
        this.tone(130.81, 0.8, 0, 0.16, { type: "sine" });
        this.tone(2093, 0.5, 0.38, 0.07, { type: "sine", attack: 0.02 });
        this.noise(0.9, 0.1, 0.05, { filterType: "bandpass", from: 800, to: 4800, q: 0.9, attack: 0.08 });
        break;
      }
      case "ambience": {
        // 一次性启动环境 pad（由调用方在 startEngine 后触发），完整音量由 startAmbience 控制
        this.startAmbience(1);
        break;
      }
      case "sprintStart": {
        // 冲刺边沿：短促上扬（快速起音锯齿 + 高频跟滑 + 噪声吐息）
        this.tone(220, 0.14, 0, 0.24, { type: "sawtooth", glide: 300, attack: 0.012 });
        this.tone(440, 0.12, 0.02, 0.12, { type: "triangle", glide: 280, attack: 0.012 });
        this.tone(880, 0.14, 0.05, 0.08, { type: "sine", glide: 200, attack: 0.015 });
        this.noise(0.16, 0, 0.07, { filterType: "bandpass", from: 700, to: 2600, q: 1, attack: 0.01 });
        break;
      }
      default:
        break;
    }
  }

  /** 启动引擎底噪（进入场景后调用一次）：saw 基频 + sub sine 低八度 + 泛音层，经同一 lowpass */
  startEngine() {
    if (!this.enabled || !this.ensure() || this.engine) return;
    if (!this.context || !this.master) return;
    if (this.context.state === "suspended") void this.context.resume();
    const context = this.context;
    const oscillator = context.createOscillator();
    const sub = context.createOscillator();
    const subGain = context.createGain();
    const gain = context.createGain();
    const filter = context.createBiquadFilter();
    oscillator.type = "sawtooth";
    oscillator.frequency.value = 55;
    sub.type = "sine";
    sub.frequency.value = 27.5;
    subGain.gain.value = 0.6;
    filter.type = "lowpass";
    filter.frequency.value = 220;
    filter.Q.value = 2.5;
    gain.gain.value = 0.0001;
    oscillator.connect(filter);
    sub.connect(subGain);
    subGain.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    oscillator.start();
    sub.start();
    gain.gain.setTargetAtTime(0.045, context.currentTime, 0.6);
    this.engine = { oscillator, sub, subGain, gain, filter };
  }

  /** 每帧喂入归一化速度 0..1，驱动频率 55→160Hz（sub 低八度跟随）与滤波开合 */
  updateEngine(speedNorm: number) {
    if (!this.engine || !this.context) return;
    const clamped = Math.min(1, Math.max(0, speedNorm));
    const target = 55 + clamped * 105;
    const now = this.context.currentTime;
    // 上缓 0.3 / 下缓 0.15（Bruno 参数）
    const rising = target > this.engineTargetRate;
    this.engineTargetRate = target;
    this.engine.oscillator.frequency.setTargetAtTime(target, now, rising ? 0.3 : 0.15);
    this.engine.sub.frequency.setTargetAtTime(target / 2, now, rising ? 0.3 : 0.15);
    this.engine.filter.frequency.setTargetAtTime(220 + clamped * 640, now, 0.2);
    const volume = clamped > 0.02 ? 0.045 : 0.02;
    this.engine.gain.gain.setTargetAtTime(volume, now, 0.25);
  }

  stopEngine() {
    if (!this.engine || !this.context) return;
    this.engine.gain.gain.setTargetAtTime(0.0001, this.context.currentTime, 0.2);
    const engine = this.engine;
    window.setTimeout(() => {
      try { engine.oscillator.stop(); } catch { /* 已停止 */ }
      try { engine.sub.stop(); } catch { /* 已停止 */ }
      engine.oscillator.disconnect();
      engine.sub.disconnect();
      engine.subGain.disconnect();
      engine.filter.disconnect();
      engine.gain.disconnect();
    }, 900);
    this.engine = null;
  }

  /**
   * 环境 pad：两个失谐锯齿 + 慢 LFO 调幅 + lowpass，音量极低垫底。
   * 幂等：重复调用只更新目标音量（revealProgress 淡入），不重复建节点。
   */
  startAmbience(revealProgress = 1) {
    if (!this.enabled || !this.ensure()) return;
    if (!this.context || !this.master) return;
    if (this.context.state === "suspended") void this.context.resume();
    const context = this.context;
    const target = 0.18 * Math.min(1, Math.max(0, revealProgress));
    if (this.ambience) {
      this.ambience.gain.gain.setTargetAtTime(target, context.currentTime, 0.8);
      return;
    }
    const oscA = context.createOscillator();
    const oscB = context.createOscillator();
    const lfo = context.createOscillator();
    const lfoGain = context.createGain();
    const gain = context.createGain();
    const filter = context.createBiquadFilter();
    oscA.type = "sawtooth";
    oscB.type = "sawtooth";
    oscA.frequency.value = 110;
    oscB.frequency.value = 110;
    // ±3 cents 失谐产生缓慢拍频，pad 更"呼吸"
    oscA.detune.value = -3;
    oscB.detune.value = 3;
    filter.type = "lowpass";
    filter.frequency.value = 880;
    filter.Q.value = 0.6;
    lfo.type = "sine";
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 0.05;
    gain.gain.value = 0.0001;
    lfo.connect(lfoGain);
    lfoGain.connect(gain.gain);
    oscA.connect(filter);
    oscB.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    oscA.start();
    oscB.start();
    lfo.start();
    gain.gain.setTargetAtTime(target, context.currentTime, 1.2);
    this.ambience = { oscA, oscB, lfo, lfoGain, gain, filter };
  }

  stopAmbience() {
    if (!this.ambience || !this.context) return;
    this.ambience.gain.gain.setTargetAtTime(0.0001, this.context.currentTime, 0.4);
    const ambience = this.ambience;
    window.setTimeout(() => {
      try { ambience.oscA.stop(); } catch { /* 已停止 */ }
      try { ambience.oscB.stop(); } catch { /* 已停止 */ }
      try { ambience.lfo.stop(); } catch { /* 已停止 */ }
      ambience.oscA.disconnect();
      ambience.oscB.disconnect();
      ambience.lfo.disconnect();
      ambience.lfoGain.disconnect();
      ambience.filter.disconnect();
      ambience.gain.disconnect();
    }, 1500);
    this.ambience = null;
  }

  setEnabled(enabled: boolean) {
    this.enabled = enabled;
    if (!enabled) {
      this.stopEngine();
      this.stopAmbience();
    }
  }

  dispose() {
    this.stopEngine();
    this.stopAmbience();
    if (this.context) {
      void this.context.close();
      this.context = null;
      this.master = null;
      this.noiseBuffer = null;
    }
  }
}

export const soundEngine = new ExperienceSoundEngine();
