import { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { useTexture, RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * CoreAgentNode - 核心智能体芯片模块
 * 业务能力：core Agent核心循环，智能大脑
 * 造型：QFP 封装芯片 + Logo 纹理
 * 方向：垂直竖立，正面朝外（+Z），Logo 面向观察者
 */
export default function CoreAgentNode({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;
  const lightRef = useRef<THREE.PointLight>(null);

  // Logo 纹理
  const logoTex = useTexture(`${import.meta.env.BASE_URL}branding/hongyunx-mark.svg`);

  // 脉冲动画
  useFrame((state) => {
    if (lightRef.current) {
      const t = state.clock.elapsedTime;
      lightRef.current.intensity = (2 + Math.sin(t * 2) * 0.8) * emissiveScale;
    }
  });

  // Color-tinted derivatives for light mode
  const shellBase = new THREE.Color(color);
  const pcbColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.7).getHexString();
  const chipBodyColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const pinColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.6).getHexString();
  const traceColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();

  // PCB 基板颜色 — 暗色注入节点色相，避免与深色背景同化
  const pcbColor = dark ? darkShell('#0a1520', color, 0.35, 0.14) : pcbColorLight;
  // 芯片封装体颜色
  const chipBodyColor = dark ? darkShell('#1a2535', color, 0.35, 0.14) : chipBodyColorLight;
  // 引脚金属色
  const pinColor = dark ? '#8a9aaa' : pinColorLight;
  // 走线颜色
  const traceColor = dark ? darkShell('#1a3040', color, 0.4, 0.16) : traceColorLight;

  return (
    <group>
      {/* ===== PCB 基板（垂直：宽 X × 高 Y × 厚 Z）===== */}
      <RoundedBox args={[1.6, 1.6, 0.12]} radius={0.04} position={[0, 0, 0]}>
        <meshStandardMaterial
          color={pcbColor}
          roughness={0.85}
          metalness={0.4}
          emissive={color}
          emissiveIntensity={0.05 * emissiveScale}
        />
      </RoundedBox>

      {/* ===== 芯片封装体（中央凸起，正面朝 +Z）===== */}
      <RoundedBox args={[0.9, 0.9, 0.25]} radius={0.06} position={[0, 0, 0.18]}>
        <meshStandardMaterial
          color={chipBodyColor}
          roughness={0.6}
          metalness={0.5}
          emissive={color}
          emissiveIntensity={0.2 * emissiveScale}
        />
      </RoundedBox>

      {/* ===== Logo 纹理贴面（正面 +Z 方向）===== */}
      <mesh position={[0, 0, 0.31]}>
        <planeGeometry args={[0.7, 0.7]} />
        <meshStandardMaterial
          map={logoTex}
          transparent
          emissive={color}
          emissiveIntensity={0.4 * emissiveScale}
          roughness={0.3}
          metalness={0.1}
        />
      </mesh>

      {/* ===== 发光环（封装体边缘，XY 平面）===== */}
      <mesh position={[0, 0, 0.06]}>
        <torusGeometry args={[0.5, 0.02, 16, 48]} />
        <meshStandardMaterial
          color={color}
          emissive={color}
          emissiveIntensity={2.0 * emissiveScale}
          roughness={0.1}
          metalness={0.2}
          transparent
          opacity={0.8}
        />
      </mesh>

      {/* ===== 脉冲点光源（正前方）===== */}
      <pointLight
        ref={lightRef}
        position={[0, 0, 0.5]}
        color={color}
        intensity={2 * emissiveScale}
        distance={2.0}
        decay={2}
      />

      {/* ===== QFP 引脚 - 四边各 8 根 ===== */}
      {/* 上边 (Y+) — 引脚向 +Z 伸出 */}
      {[...Array(8)].map((_, i) => (
        <mesh key={`pin-t-${i}`} position={[-0.56 + i * 0.16, 0.88, 0.06]}>
          <boxGeometry args={[0.04, 0.18, 0.04]} />
          <meshStandardMaterial color={pinColor} roughness={0.3} metalness={0.9} />
        </mesh>
      ))}
      {/* 下边 (Y-) */}
      {[...Array(8)].map((_, i) => (
        <mesh key={`pin-b-${i}`} position={[-0.56 + i * 0.16, -0.88, 0.06]}>
          <boxGeometry args={[0.04, 0.18, 0.04]} />
          <meshStandardMaterial color={pinColor} roughness={0.3} metalness={0.9} />
        </mesh>
      ))}
      {/* 左边 (X-) */}
      {[...Array(8)].map((_, i) => (
        <mesh key={`pin-l-${i}`} position={[-0.88, -0.56 + i * 0.16, 0.06]}>
          <boxGeometry args={[0.18, 0.04, 0.04]} />
          <meshStandardMaterial color={pinColor} roughness={0.3} metalness={0.9} />
        </mesh>
      ))}
      {/* 右边 (X+) */}
      {[...Array(8)].map((_, i) => (
        <mesh key={`pin-r-${i}`} position={[0.88, -0.56 + i * 0.16, 0.06]}>
          <boxGeometry args={[0.18, 0.04, 0.04]} />
          <meshStandardMaterial color={pinColor} roughness={0.3} metalness={0.9} />
        </mesh>
      ))}

      {/* ===== PCB 电路走线（基板正面 Z+ 表面）===== */}
      <mesh position={[0.35, 0.35, 0.065]} rotation={[0, 0, Math.PI / 4]}>
        <boxGeometry args={[0.5, 0.02, 0.008]} />
        <meshStandardMaterial
          color={traceColor}
          emissive={color}
          emissiveIntensity={0.3 * emissiveScale}
          roughness={0.7}
          metalness={0.5}
        />
      </mesh>
      <mesh position={[-0.35, 0.35, 0.065]} rotation={[0, 0, -Math.PI / 4]}>
        <boxGeometry args={[0.5, 0.02, 0.008]} />
        <meshStandardMaterial
          color={traceColor}
          emissive={color}
          emissiveIntensity={0.3 * emissiveScale}
          roughness={0.7}
          metalness={0.5}
        />
      </mesh>
      <mesh position={[-0.35, -0.35, 0.065]} rotation={[0, 0, Math.PI / 4]}>
        <boxGeometry args={[0.5, 0.02, 0.008]} />
        <meshStandardMaterial
          color={traceColor}
          emissive={color}
          emissiveIntensity={0.3 * emissiveScale}
          roughness={0.7}
          metalness={0.5}
        />
      </mesh>
      <mesh position={[0.35, -0.35, 0.065]} rotation={[0, 0, -Math.PI / 4]}>
        <boxGeometry args={[0.5, 0.02, 0.008]} />
        <meshStandardMaterial
          color={traceColor}
          emissive={color}
          emissiveIntensity={0.3 * emissiveScale}
          roughness={0.7}
          metalness={0.5}
        />
      </mesh>

      {/* ===== 四角 LED 指示点 ===== */}
      {[[-0.65, 0.65, 0.07], [0.65, 0.65, 0.07], [-0.65, -0.65, 0.07], [0.65, -0.65, 0.07]].map(
        ([x, y, z], i) => (
          <mesh key={`led-${i}`} position={[x, y, z]}>
            <sphereGeometry args={[0.03, 12, 12]} />
            <meshStandardMaterial
              color="#ffffff"
              emissive={color}
              emissiveIntensity={1.5 * emissiveScale}
              roughness={0.2}
              metalness={0.1}
            />
          </mesh>
        )
      )}
    </group>
  );
}
