import * as THREE from 'three';
import { RoundedBox } from '@react-three/drei';
import type { ModuleColorProps } from './types';
import { darkShell } from './themeUtils';

/**
 * AutomationPipeline - 自动化流水线工位模块
 * 业务能力：automation 自动化，任务流转自动执行
 */
export function AutomationPipeline({ color, dark }: ModuleColorProps) {
  const emissiveScale = dark ? 1.0 : 0.8;

  // Derive tinted light-mode colors from the node's palette color
  const shellBase = new THREE.Color(color);
  const trackColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.5).getHexString();
  const portColorLight = '#' + shellBase.clone().lerp(new THREE.Color('#ffffff'), 0.3).getHexString();

  // 暗色外壳注入节点色相，避免与深色背景同化
  const trackColor = dark ? darkShell('#1a2a30', color) : trackColorLight;
  const portColor = dark ? darkShell('#2a3a44', color) : portColorLight;
  const carrierColor = color;
  const glassColor = color;

  return (
    <group>
      {/* ===== 主轨道 ===== */}
      <mesh position={[0, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
        <capsuleGeometry args={[0.12, 0.9, 8, 16]} />
        <meshStandardMaterial
          color={trackColor}
          roughness={0.6}
          metalness={0.7}
          emissive={color}
          emissiveIntensity={0.08 * emissiveScale}
        />
      </mesh>

      {/* ===== 轨道顶部透明护罩 ===== */}
      <mesh position={[0, 0.1, 0]} rotation={[0, 0, Math.PI / 2]}>
        <capsuleGeometry args={[0.1, 0.85, 8, 16]} />
        <meshStandardMaterial
          color={glassColor}
          transparent
          opacity={0.25}
          roughness={0.8}
          metalness={0.1}
        />
      </mesh>

      {/* ===== 轨道底部支撑底座 ===== */}
      <RoundedBox args={[1.1, 0.06, 0.22]} radius={0.02} position={[0, -0.15, 0]}>
        <meshStandardMaterial
          color={trackColor}
          roughness={0.7}
          metalness={0.6}
        />
      </RoundedBox>

      {/* ===== 左侧输入端口 ===== */}
      <group position={[-0.55, 0, 0]}>
        <mesh rotation={[0, 0, Math.PI / 2]}>
          <cylinderGeometry args={[0.16, 0.14, 0.18, 16]} />
          <meshStandardMaterial
            color={portColor}
            roughness={0.5}
            metalness={0.7}
            emissive={color}
            emissiveIntensity={0.12 * emissiveScale}
          />
        </mesh>
        <mesh rotation={[0, 0, Math.PI / 2]} position={[-0.08, 0, 0]}>
          <torusGeometry args={[0.12, 0.015, 8, 24]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={0.6 * emissiveScale}
            roughness={0.3}
            metalness={0.4}
          />
        </mesh>
        <RoundedBox args={[0.04, 0.04, 0.04]} radius={0.005} position={[-0.14, 0, 0]}>
          <meshStandardMaterial
            color={carrierColor}
            emissive={color}
            emissiveIntensity={0.5 * emissiveScale}
          />
        </RoundedBox>
      </group>

      {/* ===== 右侧输出端口 ===== */}
      <group position={[0.55, 0, 0]}>
        <mesh rotation={[0, 0, Math.PI / 2]}>
          <cylinderGeometry args={[0.14, 0.16, 0.18, 16]} />
          <meshStandardMaterial
            color={portColor}
            roughness={0.5}
            metalness={0.7}
            emissive={color}
            emissiveIntensity={0.12 * emissiveScale}
          />
        </mesh>
        <mesh rotation={[0, 0, Math.PI / 2]} position={[0.08, 0, 0]}>
          <torusGeometry args={[0.12, 0.015, 8, 24]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={0.6 * emissiveScale}
            roughness={0.3}
            metalness={0.4}
          />
        </mesh>
        <RoundedBox args={[0.04, 0.04, 0.04]} radius={0.005} position={[0.14, 0, 0]}>
          <meshStandardMaterial
            color={carrierColor}
            emissive={color}
            emissiveIntensity={0.5 * emissiveScale}
          />
        </RoundedBox>
      </group>

      {/* ===== 移动任务载体 ===== */}
      <mesh position={[0, 0, 0]}>
        <boxGeometry args={[0.1, 0.1, 0.1]} />
        <meshStandardMaterial
          color={carrierColor}
          emissive={color}
          emissiveIntensity={0.5 * emissiveScale}
          roughness={0.3}
          metalness={0.5}
        />
      </mesh>

      {/* ===== 轨道中段传感器节点 ===== */}
      {[0.2, -0.2].map((xPos, i) => (
        <mesh key={i} position={[xPos, 0.13, 0]}>
          <cylinderGeometry args={[0.025, 0.025, 0.04, 12]} />
          <meshStandardMaterial
            color={color}
            emissive={color}
            emissiveIntensity={0.7 * emissiveScale}
            roughness={0.2}
            metalness={0.3}
          />
        </mesh>
      ))}

      {/* ===== 轨道侧面导轨线条 ===== */}
      {[0.1, -0.1].map((zPos, i) => (
        <mesh key={`rail-${i}`} position={[0, -0.08, zPos]} rotation={[0, 0, Math.PI / 2]}>
          <cylinderGeometry args={[0.015, 0.015, 1.0, 8]} />
          <meshStandardMaterial
            color={portColor}
            roughness={0.6}
            metalness={0.8}
          />
        </mesh>
      ))}
    </group>
  );
}
